-- Generated by tools/build_quest_data.py; references are not eligibility or a walkthrough.
return {["scripts/quests/crystalWar/WOTG_SAN_5_Perils_of_the_Griffon.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_5_Perils_of_the_Griffon.lua",["SHA256"]="3b9aaeea769e5667611c5bee04897ff66f27b238924f022384d37093a0ef940e",["Text"]="-----------------------------------\n-- Perils of the Griffon (WOTG Nation Quests - San d'Oria 5)\n-----------------------------------\n-- !addquest 7 37\n-- Rholont : !pos -168 -2 56 80\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.PERILS_OF_THE_GRIFFON)\n\nquest.reward =\n{\n    item  = xi.item.ELIXIR,\n    title = xi.title.KNIGHT_OF_THE_SWIFTWING_GRIFFIN,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.WRATH_OF_THE_GRIFFON) and\n                player:hasCompletedMission(xi.mission.log_id.WOTG, xi.mission.id.wotg.PURPLE_THE_NEW_BLACK)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        if\n                            quest:getVar(player, 'Timer') <= VanadielUniqueDay() and\n                            not quest:getMustZone(player)\n                        then\n                            return quest:progressEvent(629)\n                        else\n                            return quest:event(49)\n                        end\n                    elseif questProgress == 1 then\n                        if not quest:getMustZone(player) then\n                            return quest:progressEvent(630)\n                        else\n                            return quest:event(634)\n                        end\n                    elseif questProgress == 2 then\n                        return quest:event(635)\n                    elseif questProgress == 3 then\n                        return quest:progressEvent(632)\n                    end\n                end,\n            },\n\n            ['Daigraffeaux'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(631)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [629] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [630] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [631] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [632] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.ORCISH_WARMACHINE_BODY) then\n                        return quest:event(636)\n                    else\n                        return quest:progressEvent(633)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [633] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n\n        [xi.zone.JUGNER_FOREST_S] =\n        {\n            ['qm6'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.ORCISH_WARMACHINE_BODY) then\n                        return quest:progressEvent(210)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [210] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.ORCISH_WARMACHINE_BODY)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_6_In_a_Haze_of_Glory.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_6_In_a_Haze_of_Glory.lua",["SHA256"]="11f93a8324bfd2a50641d59356391f6399919345d73ebad292219c0350261d5a",["Text"]="-----------------------------------\n-- In a Haze of Glory (WOTG Nation Quests - San d'Oria 6)\n-----------------------------------\n-- !addquest 7 38\n-- Rholont       : !pos -168 -2 56 80\n-- Diordinne     : !pos -107.785 0 193.665 164\n-- Wooden Crates : !pos -0.717 3.347 -99.535 164\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.IN_A_HAZE_OF_GLORY)\n\nquest.reward =\n{\n    item = xi.item.FULLMETAL_BULLET,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.PERILS_OF_THE_GRIFFON)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] = quest:event(637),\n        },\n\n        [xi.zone.GARLAIGE_CITADEL_S] =\n        {\n            ['Diordinne'] = quest:progressEvent(31),\n\n            onEventFinish =\n            {\n                [31] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.NUMBER_EIGHT_SHELTER_KEY)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.GARLAIGE_CITADEL_S] =\n        {\n            ['Diordinne'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.NUMBER_EIGHT_SHELTER_KEY) then\n                        if quest:getVar(player, 'Option') == 0 then\n                            return quest:event(37)\n                        end\n                    else\n                        local questTimer = quest:getVar(player, 'Timer')\n\n                        if questTimer == 0 then\n                            return quest:progressEvent(34)\n                        elseif questTimer <= VanadielUniqueDay() then\n                            return quest:progressEvent(36)\n                        else\n                            return quest:event(35):oncePerZone()\n                        end\n                    end\n                end,\n            },\n\n            ['Wooden_Crates'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(32)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 2 then\n                    return 33\n                end\n            end,\n\n            onEventFinish =\n            {\n                [32] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [33] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [34] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                end,\n\n                [36] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Timer', 0)\n                    npcUtil.giveKeyItem(player, xi.keyItem.NUMBER_EIGHT_SHELTER_KEY)\n                end,\n\n                [37] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n\n        [xi.zone.GHOYUS_REVERIE] =\n        {\n            onEventFinish =\n            {\n                -- TODO: The assumption for this mission script is to catch Event 1000 which is\n                -- sent once the battlefield has been cleared.  This needs to be verified upon\n                -- implementation of the instance.\n                [10000] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:setPos(2.436, 6.235, -99.966, 127, xi.zone.GARLAIGE_CITADEL_S)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        if VanadielHour() >= 18 then\n                            return quest:progressEvent(82)\n                        else\n                            -- This Event is displayed the first time the condition is met, and\n                            -- then changes to 84.  They are the same message in both cases.\n\n                            return quest:event(81)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [82] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        -- NOTE: The Price of Valor also requires specific mission progress; however, it is possible to hit the below\n                        -- conditions if this is a second or third nation being completed by the player.\n\n                        xi.quest.setVar(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_PRICE_OF_VALOR, 'Timer', VanadielUniqueDay() + 1)\n                        xi.quest.setMustZone(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_PRICE_OF_VALOR)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_7_The_Price_of_Valor.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_7_The_Price_of_Valor.lua",["SHA256"]="dc695f3008f03c075883fdc6eb4a91810e8557df9ad32c195dc72cd4f473aa67",["Text"]="-----------------------------------\n-- The Price of Valor (WOTG Nation Quests - San d'Oria 7)\n-----------------------------------\n-- !addquest 7 44\n-- Rholont : !pos -168 -2 56 80\n-----------------------------------\nlocal vunkerlID = zones[xi.zone.VUNKERL_INLET_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_PRICE_OF_VALOR)\n\nquest.reward =\n{\n    item = xi.item.PEISTE_SKIN,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.IN_A_HAZE_OF_GLORY)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:getMustZone(player) and\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                    then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 0 then\n                            return quest:progressEvent(638)\n                        elseif questProgress == 1 then\n                            if\n                                player:hasKeyItem(xi.keyItem.LONG_LIFE_BISCUITS) and\n                                player:hasKeyItem(xi.keyItem.FLASK_OF_KINGDOM_WATER) and\n                                player:hasKeyItem(xi.keyItem.RONFAURE_MAPLE_SYRUP)\n                            then\n                                return quest:progressEvent(642)\n                            else\n                                return quest:event(643)\n                            end\n                        elseif questProgress == 2 then\n                            return quest:event(645)\n                        end\n                    else\n                        return quest:event(49)\n                    end\n                end,\n            },\n\n            ['Tree_Hollow'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.LONG_LIFE_BISCUITS) and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        return quest:progressEvent(640)\n                    end\n                end,\n            },\n\n            ['Well'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not player:hasKeyItem(xi.keyItem.FLASK_OF_KINGDOM_WATER) and\n                        quest:getVar(player, 'Prog') == 1\n                    then\n                        return quest:progressEvent(641)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [638] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [640] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LONG_LIFE_BISCUITS)\n                end,\n\n                [641] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.FLASK_OF_KINGDOM_WATER)\n                end,\n\n                [642] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.BISCUIT_A_LA_RHOLONT)\n\n                    player:delKeyItem(xi.keyItem.LONG_LIFE_BISCUITS)\n                    player:delKeyItem(xi.keyItem.FLASK_OF_KINGDOM_WATER)\n                    player:delKeyItem(xi.keyItem.RONFAURE_MAPLE_SYRUP)\n\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.JUGNER_FOREST_S] =\n        {\n            ['Felled_Trees'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(211)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [211] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.VUNKERL_INLET_S] =\n        {\n            ['Toppled_Cresset_1'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(202)\n                    end\n                end,\n            },\n\n            ['Toppled_Cresset_2'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(203)\n                    end\n                end,\n            },\n\n            ['Underbrush'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 4 then\n                        return quest:progressEvent(204)\n                    elseif questProgress == 5 then\n                        if quest:getLocalVar(player, 'nmDefeated') == 0 then\n                            local zoneObj = player:getZone()\n                            if not zoneObj then\n                                return\n                            end\n\n                            local mobObj  = zoneObj:queryEntitiesByName('Madthrasher_Zradbodd')[1]\n\n                            if not mobObj:isSpawned() then\n                                quest:setLocalVar(player, 'nmId', mobObj:getID())\n                                return quest:progressEvent(205)\n                            else\n                                return quest:messageSpecial(vunkerlID.text.NOW_IS_NOT_THE_TIME)\n                            end\n                        else\n                            return quest:progressEvent(206)\n                        end\n                    end\n                end,\n            },\n\n            ['Madthrasher_Zradbodd'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        quest:setLocalVar(player, 'nmDefeated', 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [202] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [203] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [204] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [205] = function(player, csid, option, npc)\n                    local mobId = quest:getLocalVar(player, 'nmId')\n\n                    SpawnMob(mobId):updateClaim(player)\n                end,\n\n                [206] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n            },\n        },\n\n        [xi.zone.PASHHOW_MARSHLANDS_S] =\n        {\n            ['Shimmering_Pondweed'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 6 then\n                        return quest:progressEvent(105)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [105] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_8_Bonds_That_Never_Die.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_8_Bonds_That_Never_Die.lua",["SHA256"]="3bcc0e7422572fe8a332b6fcb1dc8b52fb6aa3eade070e48c2493f913bbabb9e",["Text"]="-----------------------------------\n-- Bonds That Never Die (WOTG Nation Quests - San d'Oria 8)\n-----------------------------------\n-- !addquest 7 45\n-- Rholont : !pos -168 -2 56 80\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BONDS_THAT_NEVER_DIE)\n\nquest.reward =\n{\n    item = xi.item.BEHEMOTH_HORN,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_PRICE_OF_VALOR)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.LETTER_TO_COUNT_AURCHIAT) then\n                        return quest:progressEvent(649)\n                    else\n                        return quest:event(651)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [649] = function(player, csid, option, npc)\n                    npcUtil.giveKeyItem(player, xi.keyItem.LETTER_TO_COUNT_AURCHIAT)\n                end,\n            },\n        },\n\n        [xi.zone.PASHHOW_MARSHLANDS_S] =\n        {\n            ['Shimmering_Pondweed'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.LETTER_TO_COUNT_AURCHIAT) then\n                        return quest:progressEvent(107)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [107] = function(player, csid, option, npc)\n                    quest:begin(player)\n                    player:delKeyItem(xi.keyItem.LETTER_TO_COUNT_AURCHIAT)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.JUGNER_FOREST_S] =\n        {\n            ['Overgrown_Mushrooms'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:progressEvent(212)\n                    elseif\n                        questProgress == 1 and\n                        player:hasKeyItem(xi.keyItem.LENGTH_OF_JUGNER_IVY)\n                    then\n                        return quest:progressEvent(213)\n                    end\n                end,\n            },\n\n            ['Mossy_Stump'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(214)\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 4 then\n                    return 215\n                end\n            end,\n\n            onEventFinish =\n            {\n                [212] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.HATCHET) then\n                        quest:setVar(player, 'Prog', 1)\n                    end\n                end,\n\n                [213] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [214] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [215] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n            },\n        },\n\n        [xi.zone.EVERBLOOM_HOLLOW] =\n        {\n            onEventFinish =\n            {\n                [10000] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                    player:setPos(-285.717, 0.5, 88.107, 98, xi.zone.JUGNER_FOREST_S)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rongelouts_N_Distaud'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 5 then\n                        return quest:progressEvent(650)\n                    end\n                end,\n            },\n\n            ['Rholont'] = quest:event(651),\n\n            onEventFinish =\n            {\n                [650] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        quest:setVar(player, 'Option', 1)\n\n                        xi.quest.setVar(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SONGBIRDS_IN_A_SNOWSTORM, 'Timer', VanadielUniqueDay() + 1)\n                        xi.quest.setMustZone(player, xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SONGBIRDS_IN_A_SNOWSTORM)\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rongelouts_N_Distaud'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Option') == 1 then\n                        return quest:progressEvent(654)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [654] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 0)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_SAN_9_Songbirds_in_a_Snowstorm.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_SAN_9_Songbirds_in_a_Snowstorm.lua",["SHA256"]="b992c7c735283ae785f0ce0e7f3428d1e5aee306ec31eb63cc26f33f00f5629e",["Text"]="-----------------------------------\n-- Songbirds in a Snowstorm (WOTG Nation Quests - San d'Oria 9)\n-----------------------------------\n-- !addquest 7 51\n-- Rholont            : !pos -168 -2 56 80\n-- Daigraffeaux       : !pos -7 2 -89 80\n-- Colossal Footprint : !pos 82.144 -19.038 139.249 136\n-- Rocky Perch        : !pos -106.321 0.282 -365.035 136\n-- Charred Firewood   : !pos 83.296 -58.472 175.2 136\n-- Compressed Snow    : !pos 46.437 -0.762 -370.178 136\n-----------------------------------\nlocal pastBeaucedineID = zones[xi.zone.BEAUCEDINE_GLACIER_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SONGBIRDS_IN_A_SNOWSTORM)\n\nquest.reward =\n{\n    item = xi.item.ICARUS_WING,\n}\n\n-- NOTE: For fishing up the required Key Items, capture was accomplished with 0 skill, and the\n-- award message follows the format: <playername> obtained a <keyitem>!\n\n-- During capture, a Lu Shang rod was used with 0 skill at the specific ponds.  All three key\n-- items were obtained on the first attempt.  Minigame acted like a small fish (highly active),\n-- and depleted stamina within ~5 seconds of playing.\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.BONDS_THAT_NEVER_DIE) and\n                player:hasCompletedMission(xi.mission.log_id.WOTG, xi.mission.id.wotg.THE_WILL_OF_THE_WORLD)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        not quest:getMustZone(player) and\n                        quest:getVar(player, 'Timer') <= VanadielUniqueDay()\n                    then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if questProgress == 0 then\n                            return quest:progressEvent(113)\n                        elseif questProgress == 1 then\n                            if quest:getVar(player, 'Option') == 0 then\n                                return quest:progressEvent(655)\n                            else\n                                return quest:event(49)\n                            end\n                        end\n                    end\n                end,\n            },\n\n            ['Daigraffeaux'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 1 then\n                        return quest:progressEvent(114)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [113] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [114] = function(player, csid, option, npc)\n                    -- TODO: Decline option and followup needs to be captured.  Given that the event option\n                    -- returned for either selection is 0, operating under the assumption that this quest\n                    -- will be added regardless.\n\n                    quest:begin(player)\n                end,\n\n                [655] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Option', 1)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['Rholont'] = quest:event(656),\n        },\n\n        [xi.zone.BEAUCEDINE_GLACIER_S] =\n        {\n            ['Charred_Firewood'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npcUtil.tradeHasExactly(trade, xi.item.FLINT_STONE) and\n                        quest:getVar(player, 'Prog') == 4\n                    then\n                        return quest:progressEvent(4)\n                    end\n                end,\n            },\n\n            ['Colossal_Footprint'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.LANCE_FISH) and\n                        player:hasKeyItem(xi.keyItem.PALADIN_LOBSTER) and\n                        player:hasKeyItem(xi.keyItem.SCUTUM_CRAB)\n                    then\n                        return quest:progressEvent(3, 136)\n                    elseif quest:getVar(player, 'Prog') == 2 then\n                        return quest:progressEvent(2)\n                    end\n                end,\n            },\n\n            ['Compressed_Snow'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 5 then\n                        return quest:progressEvent(5)\n                    elseif\n                        questProgress == 6 and\n                        not GetMobByID(pastBeaucedineID.mob.ORCISH_BLOODLETTER):isSpawned()\n                    then\n                        return quest:progressEvent(27)\n                    elseif questProgress == 7 then\n                        return quest:progressEvent(6)\n                    end\n                end,\n            },\n\n            ['Orcish_Bloodletter'] =\n            {\n                -- TODO: Orcish Bloodletter needs verification and implementation to ensure accuracy.  Currently\n                -- is set to a very high level.\n\n                onMobDeath = function(mob, player, optParams)\n                    if quest:getVar(player, 'Prog') == 6 then\n                        quest:setVar(player, 'Prog', 7)\n                    end\n                end,\n            },\n\n            ['Rocky_Perch'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        player:messageSpecial(pastBeaucedineID.text.NONDESCRIPT_MASS)\n                        npcUtil.giveItem(player, xi.item.GOLIATH_WORM)\n\n                        return quest:noAction()\n                    end\n                end,\n            },\n\n            onZoneIn = function(player, prevZone)\n                if quest:getVar(player, 'Prog') == 1 then\n                    return 1\n                end\n            end,\n\n            onEventUpdate =\n            {\n                [1] = function(player, csid, option, npc)\n                    if option == 11 then\n                        player:updateEvent(0, 23, 1756, 0, 0, 5832718, 0, 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [2] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [3] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 4)\n                end,\n\n                [4] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [5] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 6)\n                end,\n\n                [6] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n\n                [27] = function(player, csid, option, npc)\n                    SpawnMob(pastBeaucedineID.mob.ORCISH_BLOODLETTER):updateClaim(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_WIN_0_Snake_on_the_Plains.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_WIN_0_Snake_on_the_Plains.lua",["SHA256"]="19cc28a03eb27dfeb1e73564110738aafe6da5956dc33623864589b3dd3afc06",["Text"]="-----------------------------------\n-- Snake on the Plains (WOTG Nation Quests - Windurst 0)\n-----------------------------------\n-- !addquest 7 8\n-- Miah Riyuh        : !pos 5.323 -2 37.462 94\n-- Sealed Entrance_1 : !pos -245.000 -18.100 660.000 95\n-- Sealed Entrance_2 : !pos 263.600 -6.512 40.000 95\n-- Sealed Entrance_3 : !pos -340.000 1.825 -364.825 95\n-----------------------------------\nlocal windurstWatersID   = zones[xi.zone.WINDURST_WATERS_S]\nlocal westSarutabarutaID = zones[xi.zone.WEST_SARUTABARUTA_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.SNAKE_ON_THE_PLAINS)\n\nquest.reward =\n{\n    title = xi.title.COBRA_UNIT_MERCENARY,\n}\n\nlocal otherNationAccepted = function(player)\n    return player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.STEAMED_RAMS) == xi.questStatus.QUEST_ACCEPTED or\n        player:getQuestStatus(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_FIGHTING_FOURTH) == xi.questStatus.QUEST_ACCEPTED\nend\n\nlocal sealDoor = function(player, bitNum)\n    local doors = quest:getVar(player, 'Doors')\n\n    if utils.mask.getBit(doors, bitNum) then\n        return quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 2, xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY)\n    end\n\n    local sealed = utils.mask.setBit(doors, bitNum, true)\n    quest:setVar(player, 'Doors', sealed)\n\n    if utils.mask.isFull(sealed, 3) then\n        player:delKeyItem(xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY)\n\n        return quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 4, xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY)\n    end\n\n    return quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 1, xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY)\nend\n\nlocal sealedEntrance =\n{\n    onTrigger = function(player, npc)\n        if player:hasKeyItem(xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY) then\n            -- Sealed_Entrance_1/2/3 map to door bits 0/1/2.\n            local bitNum = tonumber(string.sub(npc:getName(), -1)) - 1\n\n            return sealDoor(player, bitNum)\n        end\n\n        return quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 3)\n    end,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Miah_Riyuh'] =\n            {\n                onTrigger = function(player, npc)\n                    if otherNationAccepted(player) then\n                        return quest:event(122)\n                    elseif player:hasKeyItem(xi.keyItem.GREEN_RECOMMENDATION_LETTER) then\n                        return quest:progressEvent(103)\n                    elseif quest:getVar(player, 'LetterUsed') == 1 or player:getCampaignAllegiance() > 0 then\n                        -- Already spent a letter on a previous attempt, no second letter needed.\n                        return quest:progressEvent(105)\n                    else\n                        return quest:event(121)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [103] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY)\n                        quest:setVar(player, 'LetterUsed', 1)\n                        player:delKeyItem(xi.keyItem.GREEN_RECOMMENDATION_LETTER)\n                    elseif option == 1 then\n                        quest:setVar(player, 'LetterUsed', 1)\n                        player:delKeyItem(xi.keyItem.GREEN_RECOMMENDATION_LETTER)\n                    end\n                end,\n\n                [105] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:begin(player)\n                        npcUtil.giveKeyItem(player, xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WEST_SARUTABARUTA_S] =\n        {\n            ['Sealed_Entrance_1'] = quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 3),\n            ['Sealed_Entrance_2'] = quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 3),\n            ['Sealed_Entrance_3'] = quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 3),\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Miah_Riyuh'] =\n            {\n                onTrigger = function(player, npc)\n                    if otherNationAccepted(player) then\n                        return quest:event(122)\n                    end\n\n                    local doors = quest:getVar(player, 'Doors')\n\n                    if utils.mask.isFull(doors, 3) then\n                        return quest:progressEvent(106)\n                    elseif player:hasKeyItem(xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY) then\n                        local puttyUsed = 0\n                        for bitNum = 0, 2 do\n                            if utils.mask.getBit(doors, bitNum) then\n                                puttyUsed = puttyUsed + 1\n                            end\n                        end\n\n                        return quest:progressEvent(104, { [7] = puttyUsed })\n                    else\n                        return quest:event(121)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [104] = function(player, csid, option, npc)\n                    if option == 1 then\n                        player:delQuest(quest.areaId, quest.questId)\n                        player:delKeyItem(xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY)\n                        quest:setVar(player, 'Doors', 0)\n                    end\n                end,\n\n                [106] = function(player, csid, option, npc)\n                    if option ~= 0 then\n                        return\n                    end\n\n                    local hasNoAllegiance = player:getCampaignAllegiance() == 0\n\n                    if\n                        hasNoAllegiance and\n                        not npcUtil.giveItem(player, xi.item.SPRINTERS_SHOES)\n                    then\n                        return\n                    end\n\n                    if quest:complete(player) then\n                        if hasNoAllegiance then\n                            npcUtil.giveKeyItem(player, xi.keyItem.BRONZE_RIBBON_OF_SERVICE)\n                        end\n\n                        player:setCampaignAllegiance(3)\n                        player:messageSpecial(windurstWatersID.text.NOW_ALLIED_WITH, 3)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WEST_SARUTABARUTA_S] =\n        {\n            ['Sealed_Entrance_1'] = sealedEntrance,\n            ['Sealed_Entrance_2'] = sealedEntrance,\n            ['Sealed_Entrance_3'] = sealedEntrance,\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_COMPLETED\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Miah_Riyuh'] =\n            {\n                onTrigger = function(player, npc)\n                    if otherNationAccepted(player) then\n                        return quest:event(122)\n                    elseif player:getCampaignAllegiance() == 3 then\n                        return quest:event(107)\n                    else\n                        return quest:event(121)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WEST_SARUTABARUTA_S] =\n        {\n            ['Sealed_Entrance_1'] = quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 2, xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY):replaceDefault(),\n            ['Sealed_Entrance_2'] = quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 2, xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY):replaceDefault(),\n            ['Sealed_Entrance_3'] = quest:messageSpecial(westSarutabarutaID.text.DOOR_OFFSET + 2, xi.keyItem.ZONPA_ZIPPAS_ALL_PURPOSE_PUTTY):replaceDefault(),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_WIN_1_The_Tigress_Stirs.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_WIN_1_The_Tigress_Stirs.lua",["SHA256"]="69efb86fb6a2fb2ef74a042c358a8e75d2d80e4289af659b6443bb4acfa3eab3",["Text"]="-----------------------------------\n-- The Tigress Stirs (WOTG Nation Quests - Windurst 1)\n-----------------------------------\n-- !addquest 7 17\n-- Dhea Prandoleh              : !pos 1 -1 15 94\n-- Door:Acolyte Hostel (down)  : !pos 124 -3 222 94\n-- qm4 (West Sarutabaruta [S]) : !pos 150 -39 331 95\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_TIGRESS_STIRS)\n\nquest.reward =\n{\n    item = xi.item.HI_ELIXIR,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                xi.wotg.helpers.hasCompletedFirstQuest(player)\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Dhea_Prandoleh'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(128)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [128] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WEST_SARUTABARUTA_S] =\n        {\n            ['qm4'] =\n            {\n                onTrigger = function(player, npc)\n                    if not player:hasKeyItem(xi.keyItem.SMALL_STARFRUIT) then\n                        return quest:keyItem(xi.keyItem.SMALL_STARFRUIT)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Dhea_Prandoleh'] =\n            {\n                onTrigger = function(player, npc)\n                    -- In-progress reminder\n                    return quest:event(131)\n                end,\n            },\n\n            ['Door_Acolyte_Hostel_down'] =\n            {\n                onTrigger = function(player, npc)\n                    if player:hasKeyItem(xi.keyItem.SMALL_STARFRUIT) then\n                        return quest:progressEvent(129)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [129] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:delKeyItem(xi.keyItem.SMALL_STARFRUIT)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_WIN_2_The_Tigress_Strikes.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_WIN_2_The_Tigress_Strikes.lua",["SHA256"]="5f346013699fbacdde8dc6b135afa938d2105ff146ed021ca7cb8b662330fe47",["Text"]="-----------------------------------\n-- The Tigress Strikes (WOTG Nation Quests - Windurst 2)\n-----------------------------------\n-- !addquest 7 18\n-- Dhea Prandoleh               : !pos 1 -1 15 94\n-- Rotih Moalghett              : !pos -64 -75 4 96\n-- qm4 (Fort Karugo-Narugo [S]) : !pos 208 -30 54 96\n-----------------------------------\nlocal fortKarugoID = zones[xi.zone.FORT_KARUGO_NARUGO_S]\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_TIGRESS_STRIKES)\n\nquest.reward =\n{\n    item = xi.item.STAR_GLOBE,\n    title = xi.title.AJIDO_MARUJIDOS_MINDER,\n}\n\nquest.sections =\n{\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_TIGRESS_STIRS)\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Dhea_Prandoleh'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(133)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [133] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.FORT_KARUGO_NARUGO_S] =\n        {\n            ['Rotih_Moalghett'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 0 then\n                        return quest:progressEvent(101)\n                    else\n                        return quest:event(104)\n                    end\n                end,\n            },\n\n            ['qm4'] =\n            {\n                onTrigger = function(player, npc)\n                    local prog = quest:getVar(player, 'Prog')\n\n                    if prog == 1 then\n                        return quest:progressEvent(102)\n                    elseif quest:getVar(player, 'LynxKilled') == 1 then\n                        return quest:progressEvent(103)\n                    elseif\n                        prog == 2 and\n                        not GetMobByID(fortKarugoID.mob.TIGRESS_STRIKES_WAR_LYNX):isSpawned()\n                    then\n                        SpawnMob(fortKarugoID.mob.TIGRESS_STRIKES_WAR_LYNX):updateClaim(player)\n                        return quest:noAction()\n                    end\n                end,\n            },\n\n            ['War_Lynx'] =\n            {\n                onMobDeath = function(mob, player, optParams)\n                    if mob:getID() == fortKarugoID.mob.TIGRESS_STRIKES_WAR_LYNX then\n                        quest:setVar(player, 'LynxKilled', 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [101] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [102] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                end,\n\n                [103] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Dhea_Prandoleh'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(134)\n                    else\n                        return quest:event(135)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [134] = function(player, csid, option, npc)\n                    if quest:complete(player) then\n                        player:needToZone(true)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/crystalWar/WOTG_WIN_3_Knot_Quite_There.lua"]={["Path"]="scripts/quests/crystalWar/WOTG_WIN_3_Knot_Quite_There.lua",["SHA256"]="7c6e14ac9a6103695179455b12ee5e637ba3e6a3a2b82f4f621a78310d74d27c",["Text"]="-----------------------------------\n-- Knot Quite There (WOTG Nation Quests - Windurst 3)\n-----------------------------------\n-- !addquest 7 27\n-- Door:Acolyte Hostel : !pos 124 -3 222 94\n-- Bulwark Gate        : !pos -447 -2 342 91\n-- Door:House          : !pos 148 -3 24 80\n-----------------------------------\n\nlocal quest = Quest:new(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.KNOT_QUITE_THERE)\n\nquest.reward =\n{\n    item = xi.item.PLATINUM_BEASTCOIN,\n}\n\nquest.sections =\n{\n    -- Pick up the quest at the Acolyte Hostel door in Windurst Waters (S).\n    -- Requires The Tigress Strikes complete and WOTG mission Cait Sith current\n    -- (i.e. Back to the Beginning completed).\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_AVAILABLE and\n                player:hasCompletedQuest(xi.questLog.CRYSTAL_WAR, xi.quest.id.crystalWar.THE_TIGRESS_STRIKES) and\n                player:hasCompletedMission(xi.mission.log_id.WOTG, xi.mission.id.wotg.BACK_TO_THE_BEGINNING)\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            ['Door_Acolyte_Hostel_down'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:progressEvent(151)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [151] = function(player, csid, option, npc)\n                    quest:begin(player)\n                end,\n            },\n        },\n    },\n\n    -- Escort progression: Bulwark Gate (Sauromugue Champaign [S]) -> zone into\n    -- Southern San d'Oria (S) from East Ronfaure (S) -> Door:House.\n    {\n        check = function(player, status, vars)\n            return status == xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.WINDURST_WATERS_S] =\n        {\n            -- Reminder cutscene while the quest is active.\n            ['Door_Acolyte_Hostel_down'] =\n            {\n                onTrigger = function(player, npc)\n                    return quest:event(152)\n                end,\n            },\n        },\n\n        [xi.zone.SAUROMUGUE_CHAMPAIGN_S] =\n        {\n            ['Bulwark_Gate'] =\n            {\n                onTrigger = function(player, npc)\n                    local prog = quest:getVar(player, 'Prog')\n\n                    if prog == 0 then\n                        return quest:progressEvent(105)\n                    elseif prog == 1 then\n                        -- Pre-trade reminder to hand over the 108-Knot Quipu.\n                        return quest:event(107)\n                    elseif prog == 2 then\n                        -- Post-trade reminder to head to Southern San d'Oria.\n                        return quest:event(108)\n                    end\n                end,\n\n                onTrade = function(player, npc, trade)\n                    if\n                        quest:getVar(player, 'Prog') == 1 and\n                        npcUtil.tradeHasExactly(trade, xi.item.ONE_HUNDRED_EIGHT_KNOT_QUIPU)\n                    then\n                        return quest:progressEvent(106)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [105] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 1)\n                end,\n\n                [106] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Prog', 2)\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA_S] =\n        {\n            ['_6eo'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getVar(player, 'Prog') == 3 then\n                        return quest:progressEvent(63)\n                    end\n                end,\n            },\n\n            -- Approach cutscene with Pattna-Ottna, only when arriving on foot from\n            -- East Ronfaure (S). (Retail also suppresses it while mounted; not modeled here.)\n            onZoneIn = function(player, prevZone)\n                if\n                    prevZone == xi.zone.EAST_RONFAURE_S and\n                    quest:getVar(player, 'Prog') == 2\n                then\n                    return 62\n                end\n            end,\n\n            onEventFinish =\n            {\n                [62] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [63] = function(player, csid, option, npc)\n                    quest:complete(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/flyers_for_regine.lua"]={["Path"]="scripts/quests/flyers_for_regine.lua",["SHA256"]="772455df240e37d1d7cb3f8778f203f12b51acfecb68c4ea8c9855410efdada8",["Text"]="-----------------------------------\n-- Flyers for Regine\n-----------------------------------\n\nquests = quests or {}\nquests.flyers_for_regine = quests.flyers_for_regine or {}\n\n-----------------------------------\n-- local data\n-----------------------------------\n\n-- [ffr]deliveryMask stores delivered fliers as bits (0 = not delivered, 1 = delivered)\n-- the key in this table relates to the bit in the mask\n-- triggerArea is the area in the zone around the NPC, for trigging the approach message\n-- offset is the message that plays when approaching the NPC (offset from FFR_LOOKS_CURIOUSLY_BASE)\n\nlocal npcData =\n{\n    [xi.zone.PORT_SAN_DORIA] =\n    {\n        [ 0] = { triggerArea = 1, x =   76.331, z = -128.655, offset = 0, npc = 'Answald'  },\n        [ 1] = { triggerArea = 2, x =  -13.768, z =  -95.857, offset = 1, npc = 'Prietta'  },\n        [ 2] = { triggerArea = 3, x =    0.750, z =  -81.438, offset = 2, npc = 'Miene'    },\n        [ 3] = { triggerArea = 4, x =  -21.999, z = -106.877, offset = 3, npc = 'Portaure' },\n        [ 4] = { triggerArea = 5, x =  -37.821, z =   40.949, offset = 4, npc = 'Auvare'   },\n    },\n    [xi.zone.NORTHERN_SAN_DORIA] =\n    {\n        [ 5] = { triggerArea = 2, x =  146.420, z =  127.601, offset = 0, npc = 'Coullene'     },\n        [ 6] = { triggerArea = 3, x = -159.082, z =  253.794, offset = 1, npc = 'Guilberdrier' },\n        [ 7] = { triggerArea = 4, x = -156.242, z =   49.184, offset = 2, npc = 'Boncort'      },\n        [ 8] = { triggerArea = 5, x = -127.355, z =  130.461, offset = 3, npc = 'Capiria'      },\n        [ 9] = { triggerArea = 6, x = -157.524, z =  263.818, offset = 4, npc = 'Villion'      },\n    },\n    [xi.zone.SOUTHERN_SAN_DORIA] =\n    {\n        [10] = { triggerArea = 2, x =   33.033, z =  -30.119, offset = 0, npc = 'Blendare' },\n        [11] = { triggerArea = 3, x =   69.895, z =   41.073, offset = 1, npc = 'Rosel'    },\n        [12] = { triggerArea = 4, x =  105.147, z =  -16.735, offset = 3, npc = 'Maugie'   },\n        [13] = { triggerArea = 5, x =   80.378, z =  -24.644, offset = 5, npc = 'Adaunel'  },\n        [14] = { triggerArea = 6, x = -136.322, z =   21.958, offset = 7, npc = 'Leuveret' },\n    },\n}\n\n-----------------------------------\n-- public functions\n-----------------------------------\n\nquests.flyers_for_regine.initZone = function(zone)\n    local data = npcData[zone:getID()]\n\n    if data then\n        for _, v in pairs(data) do\n            zone:registerCylindricalTriggerArea(v.triggerArea, v.x, v.z, 10)\n        end\n    end\nend\n\nquests.flyers_for_regine.onTriggerAreaEnter = function(player, triggerArea)\n    if player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.FLYERS_FOR_REGINE) == xi.questStatus.QUEST_ACCEPTED then\n        local zoneId        = player:getZoneID()\n        local triggerAreaId = triggerArea:getTriggerAreaID()\n        local data          = npcData[zoneId]\n\n        if data then\n            for k, v in pairs(data) do\n                if v.triggerArea == triggerAreaId then\n                    local mask = player:getCharVar('[ffr]deliveryMask')\n                    local alreadyDelivered = utils.mask.getBit(mask, k)\n\n                    if not alreadyDelivered then\n                        local ID = zones[zoneId]\n                        player:messageSpecial(ID.text.FFR_LOOKS_CURIOUSLY_BASE + v.offset)\n                    end\n\n                    break\n                end\n            end\n        end\n    end\nend\n\nquests.flyers_for_regine.onTrade = function(player, npc, trade, ffrId)\n    if\n        player:getQuestStatus(xi.questLog.SANDORIA, xi.quest.id.sandoria.FLYERS_FOR_REGINE) == xi.questStatus.QUEST_ACCEPTED and\n        npcUtil.tradeHas(trade, xi.item.MAGICMART_FLYER)\n    then\n        local zoneId = player:getZoneID()\n        local ID = zones[zoneId]\n        local mask = player:getCharVar('[ffr]deliveryMask')\n        local alreadyDelivered = utils.mask.getBit(mask, ffrId)\n\n        if alreadyDelivered then\n            player:messageSpecial(ID.text.FLYER_ALREADY)\n        else\n            local data = npcData[zoneId][ffrId]\n\n            player:messageSpecial(ID.text.FLYER_ACCEPTED)\n            player:showText(npc, ID.text['FFR_' .. string.upper(data.npc)])\n            player:setCharVar('[ffr]deliveryMask', utils.mask.setBit(mask, ffrId, true))\n            player:confirmTrade()\n        end\n    end\nend\n\n-- shorthand\nquests.ffr = quests.flyers_for_regine\n"},["scripts/quests/full_speed_ahead.lua"]={["Path"]="scripts/quests/full_speed_ahead.lua",["SHA256"]="89c7b44abc3997adc95b3b0b361c8431846572d2158566b708beb19b5099104a",["Text"]="-----------------------------------\n-- Full Speed Ahead! Helper\n-----------------------------------\nlocal batalliaID = zones[xi.zone.BATALLIA_DOWNS]\n-----------------------------------\n\n--[[\nDebugging:\nStart: !setplayervar <name> [QUEST]FullSpeedAhead 1\n       !zone { Batallia Downs }\n\nReset Quest: !delquest 3 179\n\nCharVar: [QUEST]FullSpeedAhead == ...\n1 : Starting minigame on Normal Mode\n2 : Starting minigame on Easy Mode\n3 : Minigame active/playable\n4 : Minigame complete, time to hand in\n\nFULL_SPEED_AHEAD effect power:\n0 : Normal Mode\n1 : Easy Mode\n]]--\n\nxi = xi or {}\nxi.full_speed_ahead = xi.full_speed_ahead or {}\n\nxi.full_speed_ahead.duration              = 600\nxi.full_speed_ahead.motivation_decay      = 2\nxi.full_speed_ahead.motivation_food_bonus = 15\nxi.full_speed_ahead.pep_growth            = 1\n\nxi.full_speed_ahead.onEffectGain = function(player, effect)\n    player:setLocalVar('FSA_Time', GetSystemTime() + xi.full_speed_ahead.duration)\n    player:setLocalVar('FSA_Motivation', 100)\n    player:setLocalVar('FSA_Pep', 0)\n    player:setLocalVar('FSA_Food', 0xFF)\n    player:setLocalVar('FSA_FoodCount', 0)\n    -- NOTE: This used to be mount id 1: QUEST_RAPTOR, but it appears to have changed\n    player:addStatusEffect(xi.effect.MOUNTED, { power = xi.mount.RAPTOR, origin = player, tick = 3 })\n    player:setCharVar('[QUEST]FullSpeedAhead', 3)\nend\n\nxi.full_speed_ahead.onEffectLose = function(player, effect)\n    player:delStatusEffectSilent(xi.effect.MOUNTED)\n    player:countdown(0)\n    player:enableEntities({})\n\n    -- If in Batallia Downs and didn't get the completion flag (failed/dismounted)\n    if\n        player:getZoneID() == xi.zone.BATALLIA_DOWNS and\n        player:getCharVar('[QUEST]FullSpeedAhead') ~= 4\n    then\n        player:startEvent(26, 0, effect:getPower())\n    end\nend\n\nxi.full_speed_ahead.tick = function(player, effect)\n    -- TODO: slow mount speed under 50% motivation\n    -- TODO: motivation drains faster when climbing steep hills, red exclamation mark and sweat animation\n    player:setLocalVar('FSA_Motivation', player:getLocalVar('FSA_Motivation') - xi.full_speed_ahead.motivation_decay + effect:getPower())\n    player:setLocalVar('FSA_Pep', player:getLocalVar('FSA_Pep') + xi.full_speed_ahead.pep_growth + effect:getPower())\n\n    local timeLeft   = player:getLocalVar('FSA_Time') - GetSystemTime()\n    local motivation = player:getLocalVar('FSA_Motivation')\n    local pep        = player:getLocalVar('FSA_Pep')\n    local foodByte   = player:getLocalVar('FSA_Food')\n    -- local food_count = player:getLocalVar('FSA_FoodCount')\n\n    local foodData = {}\n    for i = 0, 7 do\n        if bit.band(foodByte, bit.lshift(1, i)) > 0 then\n            table.insert(foodData, batalliaID.npc.BLUE_BEAM_BASE + i)\n            table.insert(foodData, batalliaID.npc.RAPTOR_FOOD_BASE + i)\n        end\n    end\n\n    if\n        motivation <= 0 or\n        timeLeft <= 0 or\n        not player:hasStatusEffect(xi.effect.MOUNTED)\n    then\n        player:delStatusEffectSilent(xi.effect.FULL_SPEED_AHEAD)\n    else\n        local objective = {\n            countdown = timeLeft,\n            bars = {\n                [1] = {\n                    title = 'Motivation',\n                    value = motivation\n                },\n                [2] = {\n                    title = 'Pep',\n                    value = pep\n                }\n            }\n        }\n        player:objectiveUtility(objective)\n        player:enableEntities(foodData)\n    end\nend\n\nxi.full_speed_ahead.onTriggerAreaEnter = function(player, index)\n    local foodByte   = player:getLocalVar('FSA_Food')\n    local foodCount  = player:getLocalVar('FSA_FoodCount')\n    local motivation = player:getLocalVar('FSA_Motivation')\n\n    if index == 9 and foodCount >= 5 then -- Syrillia\n        player:startEvent(24) -- End CS and teleport\n    elseif bit.band(foodByte, bit.lshift(1, index - 1)) > 0 then\n        local newFoodByte = foodByte - bit.lshift(1, index - 1)\n        player:setLocalVar('FSA_Food', newFoodByte)\n        player:setLocalVar('FSA_FoodCount', foodCount + 1)\n\n        local newFoodCount  = player:getLocalVar('FSA_FoodCount')\n        local newMotivation = utils.clamp(motivation + xi.full_speed_ahead.motivation_food_bonus, 0, 100)\n        player:setLocalVar('FSA_Motivation', newMotivation)\n\n        -- Hearts\n        player:independentAnimation(player, 251, 4)\n\n        player:messageSpecial(batalliaID.text.RAPTOR_OVERCOME_MUNCHIES, newFoodCount, 5)\n\n        if newFoodCount == 5 then\n            player:messageSpecial(batalliaID.text.MEET_SYRILLIA)\n        end\n    end\nend\n\nxi.full_speed_ahead.onCheer = function(player)\n    local timeLeft   = player:getLocalVar('FSA_Time') - GetSystemTime()\n    local motivation = player:getLocalVar('FSA_Motivation')\n    local pep        = player:getLocalVar('FSA_Pep')\n\n    local newMotivation = utils.clamp(motivation + (pep / 2), 0, 100)\n\n    local objective = {\n        countdown = timeLeft,\n        bars = {\n            [1] = {\n                title = 'Motivation',\n                value = newMotivation\n            },\n            [2] = {\n                title = 'Pep',\n                value = 0\n            }\n        }\n    }\n\n    player:setLocalVar('FSA_Motivation', newMotivation)\n    player:setLocalVar('FSA_Pep', 0)\n\n    player:messageSpecial(batalliaID.text.RAPTOR_SECOND_WIND)\n\n    -- Music Notes\n    player:independentAnimation(player, 252, 4)\n\n    player:objectiveUtility(objective)\nend\n\nxi.full_speed_ahead.completeGame = function(player)\n    player:setCharVar('[QUEST]FullSpeedAhead', 4)\n    player:delStatusEffectSilent(xi.effect.FULL_SPEED_AHEAD)\n    player:setPos(-104.5, 0, 187.4, 64, 244)\nend\n\nxi.fsa = xi.full_speed_ahead\n\nreturn xi.full_speed_ahead -- NOTE: This return does nothing apart from silence the hot-reloader\n"},["scripts/quests/hiddenQuests/Chocobo_Whistle.lua"]={["Path"]="scripts/quests/hiddenQuests/Chocobo_Whistle.lua",["SHA256"]="b901dcd87dacd743d4729e2ef9a4972ebb45a3d30e4beab46b9bced49e7b271a",["Text"]="-----------------------------------\n-- Chocobo Whistle\n-----------------------------------\n-- Hantileon : !pos -2.675 -0.100 -105.287 230\n-----------------------------------\n-- Starts when a raised chocobo grows up; see xi.chocoboRaising.whistle.prog.\n-----------------------------------\nrequire('scripts/globals/hobbies/chocobo_raising/whistle')\n-----------------------------------\n\nlocal quest = HiddenQuest:new('ChocoboWhistle')\nlocal prog  = xi.chocoboRaising.whistle.prog\n\n-- Event 830 text. TODO: Nothing sends 3, the text for Hantileon's own handkerchief.\n---@enum handkerchiefText\nlocal handkerchiefText =\n{\n    DIRTY       = 1,\n    FROM_WORKER = 2,\n}\n\nlocal function startStringEvent(player, csid, ...)\n    local chocoState = player:getChocoboRaisingInfo()\n    local fullName   = ''\n    local firstName  = ''\n    local lastName   = ''\n    if chocoState then\n        fullName, firstName, lastName = xi.chocoboRaising.nameStrings(chocoState)\n    end\n\n    player:startEventString(csid, fullName, firstName, lastName, '', ...)\n\n    return quest:noAction()\nend\n\nquest.sections =\n{\n    -- Step 1: Hantileon's scene starts the search, which runs on the chocobo's walks.\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_CHOCOBO_RAISING and\n                questVars.Prog == prog.SEE_HANTILEON\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hantileon'] =\n            {\n                onTrigger = function(player, npc)\n                    return startStringEvent(player, 829, VanadielTime(), 0, 0, 2)\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [829] = function(player, csid, option, npc)\n                    -- 244 is the event asking to draw the chocobo.\n                    if option == 244 then\n                        player:updateEvent(0, 0, 1, 0, 4, 1)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [829] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', prog.SEARCH)\n                end,\n            },\n        },\n    },\n\n    -- Step 2: Bring the handkerchief back to Hantileon (Reward: Chocobo Whistle).\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_CHOCOBO_RAISING and\n                questVars.Prog == prog.FOUND\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hantileon'] =\n            {\n                onTrigger = function(player, npc)\n                    local variant = player:hasKeyItem(xi.keyItem.HANDKERCHIEF) and handkerchiefText.FROM_WORKER or handkerchiefText.DIRTY\n\n                    return startStringEvent(player, 830, VanadielTime(), variant)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [830] = function(player, csid, option, npc)\n                    if option ~= xi.chocoboRaising.whistle.option.RECEIVE_WHISTLE then\n                        return\n                    end\n\n                    xi.chocoboRaising.setWhistleProgress(player, prog.DONE)\n                    player:delKeyItem(xi.keyItem.DIRTY_HANDKERCHIEF)\n                    player:delKeyItem(xi.keyItem.HANDKERCHIEF)\n                    xi.chocoboRaising.whistle.giveQuestWhistle(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Crafted_Corsair_Artifact.lua"]={["Path"]="scripts/quests/hiddenQuests/Crafted_Corsair_Artifact.lua",["SHA256"]="70cd39b8701fdd506f9985759f757b399d77b201298bddccab5ac94dd978871c",["Text"]="-----------------------------------\n-- Crafted Corsair Artifact (COR AF)\n-----------------------------------\n-- Leleroon                                 : !pos -14.687 0.000 25.114 53\n-- Raqtibahl  (San d'Oria - Corsair's Frac) : !pos -59.000 -4.000 -39.000 232\n-- Door_House (Bastok - Corsair's Bottes)   : !pos 10.000 0.000 -16.000 234\n-- Door_House (Windurst - Corsair's Gants)  : !pos -200.000 -4.000 -111.000 238\n-----------------------------------\nlocal windurstWatersID = zones[xi.zone.WINDURST_WATERS]\nlocal bastokMinesID = zones[xi.zone.BASTOK_MINES]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('CorArtifact')\n\nlocal function finishCommission(player)\n    quest:setVarBit(player, 'Completed', quest:getVar(player, 'Option') - 1)\n    quest:setVar(player, 'Prog', 0)\n    quest:setVar(player, 'Option', 0)\n    quest:setVar(player, 'Timer', 0)\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.AGAINST_ALL_ODDS) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Door_House'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npc:getID() == bastokMinesID.npc.LELEROON_BLUE_DOOR and\n                        quest:getVar(player, 'Option') == 2\n                    then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if\n                            questProgress == 2 and\n                            npcUtil.tradeMatches(\n                                trade,\n                                {\n                                    { xi.item.MYTHRIL_SHEET,                 1 },\n                                    { xi.item.SQUARE_OF_KARAKUL_LEATHER,     1 },\n                                    { xi.item.SQUARE_OF_LM_BUFFALO_LEATHER,  1 },\n                                    { xi.item.SQUARE_OF_WOLF_FELT,           1 },\n                                }\n                            )\n                        then\n                            return quest:progressEvent(521)\n                        elseif\n                            questProgress == 3 and\n                            npcUtil.tradeMatches(trade, { { xi.item.IMPERIAL_MYTHRIL_PIECE, 4 } })\n                        then\n                            return quest:progressEvent(524)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        npc:getID() == bastokMinesID.npc.LELEROON_BLUE_DOOR and\n                        quest:getVar(player, 'Option') == 2\n                    then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if player:hasKeyItem(xi.keyItem.LELEROONS_LETTER_BLUE) then\n                            return quest:progressEvent(519)\n                        elseif questProgress == 2 then\n                            return quest:event(520)\n                        elseif questProgress == 3 then\n                            return quest:event(535)\n                        elseif questProgress == 4 then\n                            -- The piece is handed over a day later, after leaving the area.\n                            if\n                                quest:getVar(player, 'Timer') <= VanadielUniqueDay() and\n                                not quest:getMustZone(player)\n                            then\n                                return quest:progressEvent(522)\n                            else\n                                return quest:event(523)\n                            end\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [519] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:delKeyItem(xi.keyItem.LELEROONS_LETTER_BLUE)\n                end,\n\n                [521] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [522] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.CORSAIRS_BOTTES) then\n                        finishCommission(player)\n                    end\n                end,\n\n                [524] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 4)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    quest:setMustZone(player)\n                end,\n            },\n        },\n\n        [xi.zone.NASHMAU] =\n        {\n            ['Leleroon'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n                    local questOption = quest:getVar(player, 'Option')\n\n                    if questProgress >= 1 and questProgress <= 4 then\n                        if questOption == 1 then\n                            return quest:event(285)\n                        elseif questOption == 2 then\n                            return quest:event(286)\n                        elseif questOption == 3 then\n                            return quest:event(287)\n                        end\n                    elseif\n                        questProgress == 0 and\n                        quest:getVar(player, 'Completed') ~= 7\n                    then\n                        -- The introduction is only played for a first time customer.\n                        -- The menu hides a finished piece one bit above its Completed bit.\n                        return quest:progressEvent(282,\n                        {\n                            [1] = quest:getVar(player, 'Completed') ~= 0 and 1 or 0,\n                            [7] = quest:getVar(player, 'Completed') * 2,\n                        })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [282] = function(player, csid, option, npc)\n                    if\n                        option >= 1 and\n                        option <= 3 and\n                        not utils.mask.getBit(quest:getVar(player, 'Completed'), option - 1)\n                    then\n                        if option == 1 then\n                            npcUtil.giveKeyItem(player, xi.keyItem.LELEROONS_LETTER_GREEN)\n                        elseif option == 2 then\n                            npcUtil.giveKeyItem(player, xi.keyItem.LELEROONS_LETTER_BLUE)\n                        elseif option == 3 then\n                            npcUtil.giveKeyItem(player, xi.keyItem.LELEROONS_LETTER_RED)\n                        end\n\n                        quest:setVar(player, 'Option', option)\n                        quest:setVar(player, 'Prog', 1)\n                        quest:setVar(player, 'Timer', 0)\n                    end\n                end,\n            },\n        },\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            ['Raqtibahl'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if quest:getVar(player, 'Option') == 3 then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if\n                            questProgress == 2 and\n                            npcUtil.tradeMatches(\n                                trade,\n                                {\n                                    { xi.item.GOLD_CHAIN,                 1 },\n                                    { xi.item.SQUARE_OF_VELVET_CLOTH,     1 },\n                                    { xi.item.SQUARE_OF_RED_GRASS_CLOTH,  1 },\n                                    { xi.item.SQUARE_OF_SAILCLOTH,        1 },\n                                }\n                            )\n                        then\n                            return quest:progressEvent(755)\n                        elseif\n                            questProgress == 3 and\n                            npcUtil.tradeMatches(trade, { { xi.item.IMPERIAL_GOLD_PIECE, 1 } })\n                        then\n                            return quest:progressEvent(760)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if quest:getVar(player, 'Option') == 3 then\n                        if player:hasKeyItem(xi.keyItem.LELEROONS_LETTER_RED) then\n                            return quest:progressEvent(753)\n                        elseif questProgress == 2 then\n                            return quest:event(754)\n                        elseif questProgress == 3 then\n                            return quest:event(761)\n                        elseif questProgress == 4 then\n                            -- The piece is handed over a day later, after leaving the area.\n                            if\n                                quest:getVar(player, 'Timer') <= VanadielUniqueDay() and\n                                not quest:getMustZone(player)\n                            then\n                                return quest:progressEvent(756)\n                            else\n                                return quest:event(757)\n                            end\n                        end\n                    elseif utils.mask.getBit(quest:getVar(player, 'Completed'), 2) then\n                        return quest:event(758)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [753] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:delKeyItem(xi.keyItem.LELEROONS_LETTER_RED)\n                end,\n\n                [755] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [756] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.CORSAIRS_FRAC) then\n                        finishCommission(player)\n                    end\n                end,\n\n                [760] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 4)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    quest:setMustZone(player)\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            ['Door_House'] =\n            {\n                onTrade = function(player, npc, trade)\n                    if\n                        npc:getID() == windurstWatersID.npc.LELEROON_GREEN_DOOR and\n                        quest:getVar(player, 'Option') == 1\n                    then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if\n                            questProgress == 2 and\n                            npcUtil.tradeMatches(\n                                trade,\n                                {\n                                    { xi.item.SPOOL_OF_GOLD_THREAD,       1 },\n                                    { xi.item.SQUARE_OF_KARAKUL_LEATHER,  1 },\n                                    { xi.item.SQUARE_OF_RED_GRASS_CLOTH,  1 },\n                                    { xi.item.SPOOL_OF_WAMOURA_SILK,      1 },\n                                }\n                            )\n                        then\n                            return quest:progressEvent(943)\n                        elseif\n                            questProgress == 3 and\n                            npcUtil.tradeMatches(trade, { { xi.item.IMPERIAL_MYTHRIL_PIECE, 4 } })\n                        then\n                            return quest:progressEvent(946)\n                        end\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    if\n                        npc:getID() == windurstWatersID.npc.LELEROON_GREEN_DOOR and\n                        quest:getVar(player, 'Option') == 1\n                    then\n                        local questProgress = quest:getVar(player, 'Prog')\n\n                        if player:hasKeyItem(xi.keyItem.LELEROONS_LETTER_GREEN) then\n                            return quest:progressEvent(941)\n                        elseif questProgress == 2 then\n                            return quest:event(942)\n                        elseif questProgress == 3 then\n                            return quest:event(954)\n                        elseif questProgress == 4 then\n                            -- The piece is handed over a day later, after leaving the area.\n                            if\n                                quest:getVar(player, 'Timer') <= VanadielUniqueDay() and\n                                not quest:getMustZone(player)\n                            then\n                                return quest:progressEvent(944)\n                            else\n                                return quest:event(945)\n                            end\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [941] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    player:delKeyItem(xi.keyItem.LELEROONS_LETTER_GREEN)\n                end,\n\n                [943] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 3)\n                end,\n\n                [944] = function(player, csid, option, npc)\n                    if npcUtil.giveItem(player, xi.item.CORSAIRS_GANTS) then\n                        finishCommission(player)\n                    end\n                end,\n\n                [946] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    quest:setVar(player, 'Prog', 4)\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    quest:setMustZone(player)\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Crafted_Dancer_Artifact.lua"]={["Path"]="scripts/quests/hiddenQuests/Crafted_Dancer_Artifact.lua",["SHA256"]="b0ec059166b56a36a3ccd9739b41f592b570889393a37f62cc130439504a6af3",["Text"]="-----------------------------------\n-- Crafted Dancer Artifact\n-- Olgald   : !pos -53.072 -1 103.380 244\n-- Matthias : !pos -114.1 -4.29 -107.28 235\n-----------------------------------\n-- Variable Notes:\n-- * Prog   - Overall completion progress\n-- * Option - Selected Artifact\n-- * Status - Remaining Artifact Bitmask (0 = Completed)\n-- * Timer  - VanadielUniqueDay Wait Timer\n-----------------------------------\n\nlocal quest = HiddenQuest:new('DncArtifact')\n\nlocal dncArtifactOptions =\n{\n    [1] = { xi.item.DANCERS_TIARA_F,     { xi.item.SQUARE_OF_IMPERIAL_SILK_CLOTH, xi.item.SQUARE_OF_WOLF_FELT,     xi.item.SQUARE_OF_SILVER_BROCADE }, },\n    [2] = { xi.item.DANCERS_BANGLES_F,   { xi.item.SQUARE_OF_KARAKUL_CLOTH,       xi.item.SQUARE_OF_RAINBOW_CLOTH, xi.item.SQUARE_OF_RAINBOW_VELVET }, },\n    [3] = { xi.item.DANCERS_TOE_SHOES_F, { xi.item.SQUARE_OF_WAMOURA_CLOTH,       xi.item.SQUARE_OF_MOBLINWEAVE,   xi.item.SQUARE_OF_GOLD_BROCADE   }, },\n}\n\nquest.sections =\n{\n    -- Common Functions and Beginning Quest.  Note: Progress variable is set on completion of Road to Divadom in\n    -- order to prevent needing a forever CharVar.\n    {\n        check = function(player, questVars, vars)\n            return player:hasCompletedQuest(xi.questLog.JEUNO, xi.quest.id.jeuno.THE_ROAD_TO_DIVADOM) and\n                player:getMainJob() == xi.job.DNC\n        end,\n\n        [xi.zone.UPPER_JEUNO] =\n        {\n            ['Olgald'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 1 then\n                        return quest:progressEvent(10167)\n                    elseif questProgress == 2 then\n                        return quest:event(10168):oncePerZone()\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [10167] = function(player, csid, option, npc)\n                    quest:setVar(player, 'Prog', 2)\n                    quest:setVar(player, 'Status', 7)\n                end,\n            },\n        },\n    },\n\n    -- Equivalent of Accepted.  If Status == 0, then there is no remaining Artifact to be quested, and\n    -- we can treat as Completed.\n    {\n        check = function(player, questVars, vars)\n            return questVars.Prog > 0 and\n                questVars.Status > 0 and\n                player:getMainJob() == xi.job.DNC\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Matthias'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local selectedArtifact = quest:getVar(player, 'Option')\n\n                    if\n                        quest:getVar(player, 'Prog') == 4 and\n                        npcUtil.tradeHasExactly(trade, dncArtifactOptions[selectedArtifact][2])\n                    then\n                        return quest:progressEvent(495, selectedArtifact - 1)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 2 then\n                        return quest:progressEvent(492)\n                    elseif questProgress == 3 then\n                        local questStatus    = quest:getVar(player, 'Status')\n                        local completedItems = { 0, 0, 0 }\n\n                        for artifactOption = 1, 3 do\n                            if not utils.mask.getBit(questStatus, artifactOption - 1) then\n                                completedItems[artifactOption] = 1\n                            end\n                        end\n\n                        return quest:progressEvent(493, completedItems[1], completedItems[2], completedItems[3])\n                    elseif questProgress == 4 then\n                        return quest:progressEvent(494, quest:getVar(player, 'Option') - 1)\n                    elseif questProgress == 5 then\n                        if quest:getVar(player, 'Timer') <= VanadielUniqueDay() then\n                            local isLastArtifact = utils.mask.countBits(quest:getVar(player, 'Status'), 3) == 1 and 1 or 0\n\n                            return quest:progressEvent(497, dncArtifactOptions[quest:getVar(player, 'Option')][1] - player:getGender(), isLastArtifact)\n                        else\n                            return quest:progressEvent(496)\n                        end\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [492] = function(player, csid, option, npc)\n                    if option == 0 then\n                        quest:setVar(player, 'Prog', 3)\n                    else\n                        quest:setVar(player, 'Prog', 4)\n                        quest:setVar(player, 'Option', option)\n                    end\n                end,\n\n                [493] = function(player, csid, option, npc)\n                    if option ~= 0 then\n                        if utils.mask.getBit(quest:getVar(player, 'Status'), option - 1) then\n                            quest:setVar(player, 'Option', option)\n                            quest:setVar(player, 'Prog', 4)\n                        end\n                    end\n                end,\n\n                [495] = function(player, csid, option, npc)\n                    player:confirmTrade()\n                    quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    quest:setVar(player, 'Prog', 5)\n                end,\n\n                [497] = function(player, csid, option, npc)\n                    local questOption    = quest:getVar(player, 'Option')\n                    local artifactItemID = dncArtifactOptions[questOption][1] - player:getGender()\n\n                    if npcUtil.giveItem(player, artifactItemID) then\n                        if utils.mask.countBits(quest:getVar(player, 'Status'), 3) == 1 then\n                            quest:complete(player)\n                        else\n                            quest:unsetVarBit(player, 'Status', questOption - 1)\n                            quest:setVar(player, 'Prog', 3)\n                        end\n                    end\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, questVars, vars)\n            return player:findItem(xi.item.DANCERS_TIARA_F - player:getGender()) and\n                player:findItem(xi.item.DANCERS_BANGLES_F - player:getGender()) and\n                player:findItem(xi.item.DANCERS_TOE_SHOES_F - player:getGender()) and\n                player:getMainJob() == xi.job.DNC\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            ['Matthias'] = quest:progressEvent(498),\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Crafted_Magus_Artifact.lua"]={["Path"]="scripts/quests/hiddenQuests/Crafted_Magus_Artifact.lua",["SHA256"]="3220e40ee494964b741b07e13b77e88b8386a5603e9f783043a5ed46b9089670",["Text"]="-----------------------------------\n-- Crafted Magus Artifact (BLU AF)\n-----------------------------------\n-- Lathuya : !pos -95.081 -6.000 31.638 50\n-----------------------------------\n-- A commissioned piece is finished overnight: it is handed over once the Vana'diel day has changed since the fee was paid, and only after an area change.\n-- Ordering the next piece needs a second day change and another area change.\n-- The commission state stays in the [BLUAF] character variables.\n-- Transformations seeds [BLUAF]Remaining, so the container cannot own the naming.\n-----------------------------------\n\nlocal quest = HiddenQuest:new('MagusArtifact')\n\nlocal craftingItems =\n{\n    [1] = -- magus bazubands\n    {\n        materials =\n        {\n            { xi.item.PLATINUM_SHEET,            1 },\n            { xi.item.SQUARE_OF_VELVET_CLOTH,    1 },\n            { xi.item.SQUARE_OF_KARAKUL_LEATHER, 1 },\n            { xi.item.FLASK_OF_VENOM_POTION,     1 },\n        },\n        currency = xi.item.IMPERIAL_MYTHRIL_PIECE,\n        currencyAmt = 2,\n        result = xi.item.MAGUS_BAZUBANDS,\n    },\n\n    [2] = -- magus shalwar\n    {\n        materials =\n        {\n            { xi.item.GOLD_CHAIN,                    1 },\n            { xi.item.SQUARE_OF_VELVET_CLOTH,        1 },\n            { xi.item.CHUNK_OF_FLAN_MEAT,            1 },\n            { xi.item.SQUARE_OF_IMPERIAL_SILK_CLOTH, 1 },\n        },\n        currency = xi.item.IMPERIAL_MYTHRIL_PIECE,\n        currencyAmt = 2,\n        result = xi.item.MAGUS_SHALWAR,\n    },\n\n    [3] = -- magus jubbah\n    {\n        materials =\n        {\n            { xi.item.SQUARE_OF_VELVET_CLOTH,        1 },\n            { xi.item.VIAL_OF_CHIMERA_BLOOD,         1 },\n            { xi.item.SQUARE_OF_KARAKUL_CLOTH,       1 },\n            { xi.item.SQUARE_OF_IMPERIAL_SILK_CLOTH, 1 },\n        },\n        currency = xi.item.IMPERIAL_MYTHRIL_PIECE,\n        currencyAmt = 4,\n        result = xi.item.MAGUS_JUBBAH,\n    },\n}\n\nlocal function onPieceSelected(player, csid, option, npc)\n    if option < 2 or option > 9 then\n        return\n    end\n\n    local remainingBLUAF = player:getCharVar('[BLUAF]Remaining')\n\n    -- Choosing a piece.\n    if option % 3 == 2 then\n        local piece = math.floor(option / 4) + 1\n\n        -- Make sure the player isn't trying to cheat somehow\n        if utils.mask.getBit(remainingBLUAF, piece - 1) then\n            player:setCharVar('[BLUAF]Current', piece)\n\n            local materials = {}\n            for _, material in ipairs(craftingItems[piece].materials) do\n                materials[#materials + 1] = material[1]\n            end\n\n            player:updateEvent(0, unpack(materials))\n        end\n\n        return\n    end\n\n    local item = craftingItems[player:getCharVar('[BLUAF]Current')]\n\n    if item then\n        player:updateEvent(0, item.currency, item.currencyAmt)\n    end\nend\n\nlocal function onMaterialsTraded(player, csid, option, npc)\n    player:setCharVar('[BLUAF]CraftingStage', 1)\n    player:tradeComplete()\nend\n\nlocal function onFeeTraded(player, csid, option, npc)\n    player:tradeComplete()\n    player:setCharVar('[BLUAF]CraftingStage', 2)\n    player:setCharVar('[BLUAF]PaymentDay', VanadielUniqueDay())\n    quest:setMustZone(player)\n    npcUtil.giveKeyItem(player, xi.keyItem.MAGUS_ORDER_SLIP)\nend\n\nlocal function onPieceReceived(player, csid, option, npc)\n    local remainingBLUAF = player:getCharVar('[BLUAF]Remaining')\n    local currentTask    = player:getCharVar('[BLUAF]Current')\n\n    if\n        currentTask == 0 or\n        not npcUtil.giveItem(player, craftingItems[currentTask].result)\n    then\n        return\n    end\n\n    player:setCharVar('[BLUAF]Remaining', utils.mask.setBit(remainingBLUAF, currentTask - 1, false))\n    player:setCharVar('[BLUAF]PaymentDay', 0)\n    player:setCharVar('[BLUAF]CraftingStage', 0)\n    player:setCharVar('[BLUAF]Current', 0)\n\n    -- Player is finished with Lathuya\n    if player:getCharVar('[BLUAF]Remaining') == 0 then\n        player:setCharVar('[BLUAF]RestingDay', 0)\n    else\n        player:setCharVar('[BLUAF]RestingDay', VanadielUniqueDay())\n        quest:setMustZone(player)\n    end\n\n    player:delKeyItem(xi.keyItem.MAGUS_ORDER_SLIP)\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.TRANSFORMATIONS) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Lathuya'] =\n            {\n                onTrade = function(player, npc, trade)\n                    local remainingBLUAF = player:getCharVar('[BLUAF]Remaining')\n                    local item           = craftingItems[player:getCharVar('[BLUAF]Current')]\n\n                    if\n                        remainingBLUAF == 0 or\n                        not item\n                    then\n                        return\n                    end\n\n                    local craftingStage  = player:getCharVar('[BLUAF]CraftingStage')\n                    local artifactOffset = 8 * (3 - utils.mask.countBits(remainingBLUAF, 3))\n\n                    if\n                        craftingStage == 0 and\n                        npcUtil.tradeMatches(trade, item.materials)\n                    then\n                        return quest:progressEvent(732 + artifactOffset, item.result, item.currency, item.currencyAmt)\n                    elseif\n                        craftingStage == 1 and\n                        npcUtil.tradeMatches(trade, { { item.currency, item.currencyAmt } })\n                    then\n                        return quest:progressEvent(734 + artifactOffset, 0, item.currency, item.currencyAmt)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local remainingBLUAF     = player:getCharVar('[BLUAF]Remaining')\n                    local totalCraftedPieces = 3 - utils.mask.countBits(remainingBLUAF, 3)\n                    local currentTask        = player:getCharVar('[BLUAF]Current')\n                    local craftingStage      = player:getCharVar('[BLUAF]CraftingStage')\n                    local artifactOffset     = 8 * totalCraftedPieces\n\n                    -- No order placed, and there is still a piece left to make.\n                    if currentTask == 0 and totalCraftedPieces ~= 3 then\n                        -- The next order is taken a day later, after leaving the area.\n                        if\n                            VanadielUniqueDay() > player:getCharVar('[BLUAF]RestingDay') and\n                            not quest:getMustZone(player)\n                        then\n                            -- Only one piece is left, so there is nothing to choose.\n                            if totalCraftedPieces == 2 then\n                                return quest:progressEvent(746, { [7] = math.floor(remainingBLUAF / 2) + 1 })\n                            end\n\n                            -- Will prompt for choosing which armor to work on\n                            return quest:progressEvent(730 + artifactOffset, 7 - remainingBLUAF)\n                        end\n\n                        return quest:event(737 + (artifactOffset - 8)) -- Asleep message, wait until 1 day passes\n\n                    -- An order is in progress.\n                    elseif currentTask > 0 then\n                        local item = craftingItems[currentTask]\n\n                        if craftingStage == 0 then\n                            return quest:event(731 + artifactOffset, 0, item.currency, item.currencyAmt)\n                        elseif craftingStage == 1 then\n                            return quest:event(733 + artifactOffset, item.result, item.currency, item.currencyAmt)\n                        end\n\n                        -- The piece is handed over a day later, after leaving the area.\n                        if\n                            VanadielUniqueDay() > player:getCharVar('[BLUAF]PaymentDay') and\n                            not quest:getMustZone(player)\n                        then\n                            return quest:progressEvent(736 + artifactOffset, item.result)\n                        end\n\n                        return quest:event(735 + artifactOffset)\n                    end\n\n                    return quest:event(753):replaceDefault() -- Dialogue after crafting all BLU AF\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [730] = onPieceSelected,\n                [738] = onPieceSelected,\n                [746] = onPieceSelected,\n            },\n\n            onEventFinish =\n            {\n                [732] = onMaterialsTraded,\n                [740] = onMaterialsTraded,\n                [748] = onMaterialsTraded,\n\n                [734] = onFeeTraded,\n                [742] = onFeeTraded,\n                [750] = onFeeTraded,\n\n                [736] = onPieceReceived,\n                [744] = onPieceReceived,\n                [752] = onPieceReceived,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Crafted_Puppetry_Artifact.lua"]={["Path"]="scripts/quests/hiddenQuests/Crafted_Puppetry_Artifact.lua",["SHA256"]="5fd3b91d76cf94860c056d7e933dd4719be62df1f48b395c2ccce094bc9699ff",["Text"]="-----------------------------------\n-- Crafted Puppetry Artifact (PUP AF)\n-----------------------------------\n-- Dhima Polevhia : !pos 67.802 -6.000 26.315 50\n-----------------------------------\n-- Dhima finishes a piece overnight: it is handed over once the Vana'diel day has changed since the materials were traded.\n-- No area change is needed, and the next order can be placed straight away.\n-- The commission state stays in the [PUP] character variables.\n-- [AF]pupCrafted is shared with the artifact reset system, so the container cannot own the naming.\n-----------------------------------\n\nlocal quest = HiddenQuest:new('PuppetryArtifact')\n\nlocal pieceBits =\n{\n    [xi.item.PUPPETRY_TOBE     ] = 1,\n    [xi.item.PUPPETRY_DASTANAS ] = 2,\n    [xi.item.PUPPETRY_BABOUCHES] = 3,\n}\n\nlocal tradeTable =\n{\n    [xi.item.PUPPETRY_TOBE] =\n    {\n        [1] = { xi.item.RUBY,                          1 },\n        [2] = { xi.item.SQUARE_OF_MOBLINWEAVE,         1 },\n        [3] = { xi.item.SQUARE_OF_SCARLET_LINEN_CLOTH, 1 },\n        [4] = { xi.item.SQUARE_OF_WAMOURA_CLOTH,       1 },\n        [5] = { xi.item.IMPERIAL_GOLD_PIECE,           1 },\n    },\n    [xi.item.PUPPETRY_DASTANAS] =\n    {\n        [1] = { xi.item.PLATINUM_SHEET,          1 },\n        [2] = { xi.item.SPOOL_OF_RAINBOW_THREAD, 1 },\n        [3] = { xi.item.SQUARE_OF_MARID_LEATHER, 1 },\n        [4] = { xi.item.SQUARE_OF_WAMOURA_CLOTH, 1 },\n        [5] = { xi.item.IMPERIAL_MYTHRIL_PIECE,  1 },\n    },\n    [xi.item.PUPPETRY_BABOUCHES] =\n    {\n        [1] = { xi.item.PLATINUM_SHEET,          1 },\n        [2] = { xi.item.RUBY,                    1 },\n        [3] = { xi.item.SQUARE_OF_MARID_LEATHER, 1 },\n        [4] = { xi.item.SQUARE_OF_WAMOURA_CLOTH, 1 },\n        [5] = { xi.item.IMPERIAL_MYTHRIL_PIECE,  2 },\n    },\n}\n\nlocal orderedPieces =\n{\n    [1] = xi.item.PUPPETRY_TOBE,\n    [2] = xi.item.PUPPETRY_DASTANAS,\n    [3] = xi.item.PUPPETRY_BABOUCHES,\n}\n\nlocal function onOrderPlaced(player, csid, option, npc)\n    if orderedPieces[option] then\n        player:setCharVar('[PUP]orderId', orderedPieces[option])\n        player:setCharVar('[PUP]orderStage', 1)\n    end\nend\n\nlocal function onOrderReceived(player, csid, option, npc)\n    local orderId = player:getCharVar('[PUP]orderId')\n\n    if npcUtil.giveItem(player, orderId) then\n        player:incrementCharVar('[AF]pupCrafted', bit.lshift(1, pieceBits[orderId]))\n        player:setCharVar('[PUP]orderId', 0)\n        player:setCharVar('[PUP]orderStage', 0)\n        player:setCharVar('[PUP]orderTime', 0)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return player:getQuestStatus(xi.questLog.AHT_URHGAN, xi.quest.id.ahtUrhgan.PUPPETMASTER_BLUES) >= xi.questStatus.QUEST_ACCEPTED\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Dhima_Polevhia'] =\n            {\n                onTrade = function(player, npc, trade)\n                    -- Materials are only accepted while an order is waiting on them.\n                    if player:getCharVar('[PUP]orderStage') ~= 1 then\n                        return\n                    end\n\n                    local recipe = tradeTable[player:getCharVar('[PUP]orderId')]\n\n                    if\n                        recipe and\n                        npcUtil.tradeMatches(trade, recipe)\n                    then\n                        return quest:progressEvent(795)\n                    end\n                end,\n\n                onTrigger = function(player, npc)\n                    local piecesBitmask = player:getCharVar('[AF]pupCrafted')\n                    local piecesNumber  = utils.mask.countBits(piecesBitmask, 4)\n                    local orderId       = player:getCharVar('[PUP]orderId')\n                    local orderStage    = player:getCharVar('[PUP]orderStage')\n                    local orderTime     = player:getCharVar('[PUP]orderTime')\n\n                    -- Trade completed. Check time.\n                    if orderStage == 2 then\n                        if VanadielUniqueDay() > orderTime then\n                            if piecesNumber == 2 then\n                                return quest:progressEvent(793) -- Order is ready. Last time.\n                            end\n\n                            return quest:progressEvent(792) -- Order is ready. First and second time.\n                        end\n\n                        return quest:event(796) -- Order is not ready.\n\n                    -- Placed order. Waiting for trade.\n                    elseif orderStage == 1 then\n                        return quest:event(790, 0, 0, 0, pieceBits[orderId])\n\n                    -- Has made all pieces already.\n                    elseif piecesNumber == 3 then\n                        return quest:event(788):replaceDefault()\n\n                    -- Place order. (Not first time).\n                    elseif piecesNumber > 0 then\n                        return quest:progressEvent(791, 0, piecesBitmask)\n                    end\n\n                    -- Place order. (First time)\n                    return quest:progressEvent(789)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [789] = onOrderPlaced,\n                [791] = onOrderPlaced,\n\n                [792] = onOrderReceived,\n                [793] = onOrderReceived,\n\n                [795] = function(player, csid, option, npc)\n                    player:tradeComplete()\n                    player:setCharVar('[PUP]orderStage', 2)\n                    player:setCharVar('[PUP]orderTime', VanadielUniqueDay())\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Crimson_Orb.lua"]={["Path"]="scripts/quests/hiddenQuests/Crimson_Orb.lua",["SHA256"]="0217b61f92c8961c062a6600380cf78e49b4f7bd4964727653a1194c11746585",["Text"]="-----------------------------------\n-- Crimson Orb\n-----------------------------------\n-- Wall of Banishing : !pos 181 0.1 -218 149\n-- Sedal-Godjal      : !pos 185 -3 -116 149\n-- Groaning Pond     : !pos 101 0.1 60 149\n-- Howling Pond      : !pos 21 0.1 -258 149\n-- Wailing Pond      : !pos 380 0.1 -181 149\n-- Screaming Pond    : !pos -219 0.1 -101 149\n-----------------------------------\nlocal davoiID = zones[xi.zone.DAVOI]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('CrimsonOrb')\n\nquest.reward =\n{\n    keyItem = xi.keyItem.CRIMSON_ORB,\n}\n\nlocal pondNpcs =\n{\n    '_45g',\n    '_45h',\n    '_45i',\n    '_45j',\n}\n\n-- The below functions handle the logic for all ponds.  NPC Offset is 0-indexed (50..53), and derived\n-- from the table above.  While we set all 4 bits, the ponds themselves only care about themselves, and\n-- if it is the last pond in sequence (numPonds == 3) to change the event animation.\nlocal pondOnTrigger = function(player, npc)\n    local npcName = npc:getName()\n    local npcOffset = 0\n    local questOption = quest:getVar(player, 'Option')\n    local numPonds = utils.mask.countBits(questOption, 4)\n\n    for offsetValue, npcListName in ipairs(pondNpcs) do\n        if npcName == npcListName then\n            npcOffset = offsetValue - 1\n            break\n        end\n    end\n\n    if\n        quest:getVar(player, 'Prog') == 2 and\n        not utils.mask.getBit(questOption, npcOffset)\n    then\n        quest:setLocalVar(player, 'npcOffset', npcOffset)\n        player:messageSpecial(davoiID.text.ORB_QUEST_OFFSET)\n        return quest:progressCutscene(50 + npcOffset, 0, numPonds, player:getRace())\n    end\n\n    -- Intentional fallthrough to default action (Pool is the color of blood)\nend\n\nlocal pondEventFinish = function(player, csid, option, npc)\n    local questOption = quest:getVar(player, 'Option')\n    local npcOffset = quest:getLocalVar(player, 'npcOffset')\n    local numPonds = utils.mask.countBits(questOption, 4)\n\n    quest:setVarBit(player, 'Option', npcOffset)\n    player:messageSpecial(davoiID.text.ORB_QUEST_OFFSET + numPonds + 1, 0, 0, 0, xi.keyItem.WHITE_ORB + numPonds + 1)\n    player:delKeyItem(xi.keyItem.WHITE_ORB + numPonds)\n    player:addKeyItem(xi.keyItem.WHITE_ORB + numPonds + 1)\n\n    if numPonds == 3 then\n        player:addStatusEffect(xi.effect.CURSE_I, { power = 50, duration = 600, origin = player })\n        player:messageSpecial(davoiID.text.ORB_QUEST_OFFSET + 5)\n        quest:setVar(player, 'Prog', 3)\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return not player:hasKeyItem(xi.keyItem.CRIMSON_ORB)\n        end,\n\n        [xi.zone.DAVOI] =\n        {\n            ['_45d'] = -- Wall of Banishing\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress <= 1 then\n                        quest:setVar(player, 'Prog', 1)\n                        -- Intentional fallthrough to default action (Cave is sealed off)\n                    elseif questProgress >= 2 then\n                        return quest:messageSpecial(davoiID.text.MAY_BE_SOME_WAY_TO_BREAK)\n                    end\n                end,\n            },\n\n            ['_45g'] =\n            {\n                onTrigger = pondOnTrigger,\n            },\n\n            ['_45h'] =\n            {\n                onTrigger = pondOnTrigger,\n            },\n\n            ['_45i'] =\n            {\n                onTrigger = pondOnTrigger,\n            },\n\n            ['_45j'] =\n            {\n                onTrigger = pondOnTrigger,\n            },\n\n            ['Sedal-Godjal'] =\n            {\n                onTrigger = function(player, npc)\n                    local questProgress = quest:getVar(player, 'Prog')\n\n                    if questProgress == 0 then\n                        return quest:event(24, { canSkip = true }):replaceDefault()\n                    elseif questProgress == 1 then\n                        return quest:progressEvent(22, { canSkip = true })\n                    elseif questProgress == 2 then\n                        return quest:event(21, { canSkip = true })\n                    elseif questProgress == 3 then\n                        return quest:progressCutscene(25, 0, 0, 0, 136)\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [22] = function(player, csid, option, npc)\n                    if option == 1 then\n                        quest:setVar(player, 'Prog', 2)\n                        npcUtil.giveKeyItem(player, xi.keyItem.WHITE_ORB)\n                    end\n                end,\n\n                [25] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.CURSED_ORB)\n                    quest:complete(player)\n                end,\n\n                [50] = pondEventFinish,\n                [51] = pondEventFinish,\n                [52] = pondEventFinish,\n                [53] = pondEventFinish,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Invitation_Cards.lua"]={["Path"]="scripts/quests/hiddenQuests/Invitation_Cards.lua",["SHA256"]="bd07a2ac0461a1d0d3539b96dbf8650b57ca2f9f77ce4f7e9707bb5b0304aabd",["Text"]="-----------------------------------\n-- Lure of the Wildcat Invitation Cards\n\n-- Naja: !pos 22.700 -8.804 -45.591 50\n-----------------------------------\n\nlocal quest = HiddenQuest:new('Invitation_Cards')\n\nlocal invitationCards =\n{\n    xi.keyItem.RED_INVITATION_CARD,\n    xi.keyItem.BLUE_INVITATION_CARD,\n    xi.keyItem.GREEN_INVITATION_CARD,\n    xi.keyItem.WHITE_INVITATION_CARD,\n}\n\nlocal rewards =\n{\n    [0] = { coin = 0,                               amount = 0 },\n    [1] = { coin = xi.item.IMPERIAL_BRONZE_PIECE,  amount = 1 },\n    [2] = { coin = xi.item.IMPERIAL_BRONZE_PIECE,  amount = 2 },\n    [3] = { coin = xi.item.IMPERIAL_BRONZE_PIECE,  amount = 3 },\n    [4] = { coin = xi.item.IMPERIAL_MYTHRIL_PIECE, amount = 1 },\n}\n\nlocal function getCards(player)\n    local numCards = 0\n\n    for _, tempKeyItem in pairs(invitationCards) do\n        if player:hasKeyItem(tempKeyItem) then\n            numCards = numCards + 1\n        end\n    end\n\n    return numCards, rewards[numCards].coin, rewards[numCards].amount\nend\n\nlocal function deleteCards(player)\n    for _, tempKeyItem in pairs(invitationCards) do\n        if player:hasKeyItem(tempKeyItem) then\n            player:delKeyItem(tempKeyItem)\n        end\n    end\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return getCards(player) > 0\n        end,\n\n        [xi.zone.AHT_URHGAN_WHITEGATE] =\n        {\n            ['Naja_Salaheem'] =\n            {\n                onTrigger = function(player, npc)\n                    if quest:getLocalVar(player, 'Option') == 0 then\n                        if quest:getVar(player, 'Prog') == 0 then\n                            return quest:progressEvent(74, { text_table = 0 })\n                        else\n                            return quest:progressEvent(75, { text_table = 0 })\n                        end\n                    end\n                end,\n            },\n\n            onEventUpdate =\n            {\n                [74] = function(player, csid, option, npc)\n                    if option == 1 then\n                        local cards, coin, amount = getCards(player)\n\n                        player:updateEvent({ [0] = cards, [1] = coin, [2] = amount, text_table = 0 })\n                    end\n                end,\n\n                [75] = function(player, csid, option, npc)\n                    if option == 1 then\n                        local cards, _, _ = getCards(player)\n\n                        player:updateEvent({ [0] = cards, [1] = xi.item.IMPERIAL_BRONZE_PIECE, [2] = 1, text_table = 0 })\n                    end\n                end,\n            },\n\n            onEventFinish =\n            {\n                [74] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Option', 1)\n\n                    if option == 3 then\n                        local cards, coin, amount = getCards(player)\n\n                        if npcUtil.giveItem(player, { { coin, amount } }) then\n                            deleteCards(player)\n\n                            if cards < 4 then\n                                quest:setVar(player, 'Prog', cards)\n                            end\n                        end\n                    end\n                end,\n\n                [75] = function(player, csid, option, npc)\n                    quest:setLocalVar(player, 'Option', 1)\n\n                    if option == 3 then\n                        local cards, _, _ = getCards(player)\n\n                        if npcUtil.giveItem(player, xi.item.IMPERIAL_BRONZE_PIECE) then\n                            deleteCards(player)\n\n                            local count = quest:getVar(player, 'Prog')\n                            if cards + count >= 4 then\n                                quest:complete(player)\n                            else\n                                quest:setVar(player, 'Prog', count + cards)\n                            end\n                        end\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Lost_Chick.lua"]={["Path"]="scripts/quests/hiddenQuests/Lost_Chick.lua",["SHA256"]="ae82a60b2d7388769555d1c3cba20d503a7f6c3e81138c1031471fb2aa1efffe",["Text"]="-----------------------------------\n-- Lost Chick\n-----------------------------------\n-- Hantileon : !pos -2.675 -0.100 -105.287 230\n-- Zopago    : !pos 51.706 0.874 -109.065 234\n-- Pulonono  : !pos 130.124 -6.350 -119.341 241\n-- Owners    : xi.chocoboRaising.walks.chickOwners\n-----------------------------------\n-- A chick's short walk finds a lost chick, trainers met on later walks give clues to its owner, and\n-- the stable clerk reviews them. The right owner teaches the diligent story; any guess ends the\n-- search, and the trainer reports how it went. State: xi.chocoboRaising.walks.lostChickVar.\n-----------------------------------\nrequire('scripts/globals/hobbies/chocobo_raising/constants')\nrequire('scripts/globals/hobbies/chocobo_raising/walks')\n-----------------------------------\n\nlocal quest = HiddenQuest:new('LostChick')\nlocal walks = xi.chocoboRaising.walks\n\nlocal function ownerUpdate(location, ownerId, owner)\n    return function(player, csid, option, npc)\n        if not npc or npc:getName() ~= owner.npc then\n            return\n        end\n\n        local choice = bit.band(option, 0xFFFF)\n\n        -- Inline events offer the question only when p1 is 1.\n        if choice == owner.ask then\n            quest:setLocalVar(player, 'Asked', 1)\n            player:updateEvent(1, 1, 1)\n        elseif choice == owner.guess then\n            -- An inline event's own options share the guess value, so only the one after the ask counts.\n            if owner.ask then\n                if quest:getLocalVar(player, 'Asked') == 0 then\n                    return\n                end\n\n                quest:setLocalVar(player, 'Asked', 0)\n            end\n\n            local right, effects = walks.askOwner(player:getCharVar(walks.lostChickVar), location, ownerId)\n            local answer         = right and 1 or 0\n\n            -- Each owner event reads the answer from a different param, so it goes in p0 to p2.\n            player:updateEvent(answer, answer, answer)\n            xi.chocoboRaising.applyEffects(player, effects)\n\n            if right then\n                player:messageSpecial(zones[player:getZoneID()].text.KEYITEM_OBTAINED, xi.keyItem.STORY_OF_A_DILIGENT_CHOCOBO)\n            end\n        elseif owner.mapVendorEvent then\n            xi.maps.onEventUpdate(player, owner.mapVendorEvent, option, npc)\n        end\n    end\nend\n\n-- Owners without an ask option play their question event on trigger.\nlocal function ownerZone(location)\n    local zone = { onEventUpdate = {} }\n\n    for ownerId, owner in pairs(walks.chickOwners[location]) do\n        if not owner.ask then\n            zone[owner.npc] = quest:priorityEvent(owner.events[1], 1)\n        end\n\n        for _, csid in ipairs(owner.events) do\n            zone.onEventUpdate[csid] = ownerUpdate(location, ownerId, owner)\n        end\n    end\n\n    return zone\nend\n\n-- The trainer's closing scene. p0 picks the line: 0 the owner came for the chick, 1 the trainer took it back.\nlocal function reportEvent(player, csid, location)\n    local returned = walks.lostChick(player:getCharVar(walks.lostChickVar)).result == walks.lostChickResult.RETURNED and 1 or 0\n\n    return quest:progressEvent(csid, { [0] = 1 - returned, [1] = returned, [7] = location })\nend\n\nlocal function chickAt(player, location)\n    if not xi.settings.main.ENABLE_CHOCOBO_RAISING then\n        return false\n    end\n\n    local chick = walks.lostChick(player:getCharVar(walks.lostChickVar))\n\n    return chick.owner ~= 0 and chick.location == location\nend\n\nquest.sections =\n{\n    -- Step 1: Ask the San d'Oria owners about the lost chick. The right one teaches the diligent story.\n    {\n        check = function(player, questVars, vars)\n            return chickAt(player, 1)\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] = ownerZone(1),\n    },\n\n    -- Step 1: Ask the Bastok owners about the lost chick.\n    {\n        check = function(player, questVars, vars)\n            return chickAt(player, 2)\n        end,\n\n        [xi.zone.BASTOK_MINES] = ownerZone(2),\n    },\n\n    -- Step 1: Ask the Windurst owners about the lost chick.\n    {\n        check = function(player, questVars, vars)\n            return chickAt(player, 3)\n        end,\n\n        [xi.zone.WINDURST_WOODS] = ownerZone(3),\n    },\n\n    -- Step 2: The trainer reports how the search went and clears the result.\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_CHOCOBO_RAISING and\n                walks.lostChick(player:getCharVar(walks.lostChickVar)).result ~= walks.lostChickResult.NONE\n        end,\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            ['Hantileon'] =\n            {\n                onTrigger = function(player, npc)\n                    return reportEvent(player, 852, 1)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [852] = function(player, csid, option, npc)\n                    xi.chocoboRaising.applyEffects(player, walks.clearLostChickResult(player:getCharVar(walks.lostChickVar)))\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            ['Zopago'] =\n            {\n                onTrigger = function(player, npc)\n                    return reportEvent(player, 542, 2)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [542] = function(player, csid, option, npc)\n                    xi.chocoboRaising.applyEffects(player, walks.clearLostChickResult(player:getCharVar(walks.lostChickVar)))\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            ['Pulonono'] =\n            {\n                onTrigger = function(player, npc)\n                    return reportEvent(player, 766, 3)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [766] = function(player, csid, option, npc)\n                    xi.chocoboRaising.applyEffects(player, walks.clearLostChickResult(player:getCharVar(walks.lostChickVar)))\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Mimeo_Stone.lua"]={["Path"]="scripts/quests/hiddenQuests/Mimeo_Stone.lua",["SHA256"]="f40f96d5d5c010853390a5acf2a2f1c2a1140e9a81ba396a96bcd310188e1222",["Text"]="-----------------------------------\n-- Mimeo Stone\n-----------------------------------\n-- Luminant : !pos 241.833 19.009 -152.072\n-- Luminant : !pos 444.687 19.697 -172.114\n-- Luminant : !pos 514.630 19.328 -79.209\n-- Luminant : !pos 275.930 19.229 153.760\n-- Luminant : !pos 197.387 19.977 -56.561\n-- Luminant : !pos 442.997 19.500 -34.534\n-- Cradle of Rebirth : !pos 319.958 -25.652 -11.895\n-----------------------------------\n\nlocal quest = HiddenQuest:new('mimeoStone')\nlocal ID = zones[xi.zone.ATTOHWA_CHASM]\nlocal attohwaChasmGlobal = require('scripts/zones/Attohwa_Chasm/globals')\n\nlocal rewards =\n{\n    [0] = xi.item.REGAIN_FEATHER,\n    [1] = xi.item.REBIRTH_FEATHER,\n    [2] = xi.item.REVIVE_FEATHER,\n    [3] = xi.item.BLAZE_FEATHER,\n    [4] = xi.item.FIRE_FEATHER\n}\n\nlocal stoneTimer\nstoneTimer = function(player)\n    -- Once the animation at the Cradle has started, the reward has already been locked in\n    -- so don't continue the timer after this point\n    if\n        not player or\n        not player:hasKeyItem(xi.keyItem.MIMEO_STONE) or\n        quest:getLocalVar(player, 'Progress') == 1\n    then\n        return\n    end\n\n    local numFades = quest:getLocalVar(player, 'NumFades') + 1\n    if numFades == 5 then\n        player:messageSpecial(ID.text.MIMEO_JEWEL_OFFSET + 4, xi.keyItem.MIMEO_STONE)\n        player:delKeyItem(xi.keyItem.MIMEO_STONE)\n        return\n    end\n\n    quest:setLocalVar(player, 'NumFades', numFades)\n\n    player:messageSpecial(ID.text.MIMEO_JEWEL_OFFSET + numFades - 1, xi.keyItem.MIMEO_STONE)\n\n    -- Captures show ranges from 49 to 88, but it may not necessarily be purely random\n    -- For Luminant Offset+3, all times (12 recorded) were below 60s except 1\n    -- For all other Luminants, there were no times below 60s (14 recorded)\n    -- There could be some subtle differences based on the Luminant distance to the Cradle,\n    -- but unless we get a hundred more times captured this is probably the best we can do.\n    player:timer(math.randomInt(50, 90) * 1000, function()\n        stoneTimer(player)\n    end)\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return not player:hasKeyItem(xi.keyItem.MIMEO_STONE)\n        end,\n\n        [xi.zone.ATTOHWA_CHASM] =\n        {\n            ['Luminant'] =\n            {\n                onTrigger = function(player, npc, trade)\n                    npcUtil.giveKeyItem(player, xi.keyItem.MIMEO_STONE)\n                    player:messageSpecial(ID.text.MIMEO_STONE_PICKUP, xi.keyItem.MIMEO_STONE)\n\n                    attohwaChasmGlobal.handleLuminantUsed(npc)\n\n                    quest:setLocalVar(player, 'NumFades', 0)\n                    quest:setLocalVar(player, 'Progress', 0)\n\n                    player:timer(math.randomInt(50, 90) * 1000, function()\n                        stoneTimer(player)\n                    end)\n                end,\n            },\n        },\n    },\n\n    {\n        check = function(player, questVars, vars)\n            return player:hasKeyItem(xi.keyItem.MIMEO_STONE)\n        end,\n\n        [xi.zone.ATTOHWA_CHASM] =\n        {\n            ['Luminant'] =\n            {\n                onTrigger = function(player, npc)\n                    player:messageSpecial(ID.text.NOTHING_OUT_OF_ORDINARY)\n                end\n            },\n\n            ['Cradle_of_Rebirth'] =\n            {\n                onTrigger = function(player, npc)\n                    if\n                        player:hasKeyItem(xi.keyItem.MIMEO_STONE) and\n                        quest:getLocalVar(player, 'Progress') == 0\n                    then\n                        local numFades = quest:getLocalVar(player, 'NumFades')\n                        player:messageSpecial(ID.text.MIMEO_STONE_BRIGHTNESS_OFFSET + numFades, xi.keyItem.MIMEO_STONE)\n\n                        -- Make sure player has room for reward, otherwise timer keeps running\n                        local reward = rewards[numFades]\n                        if player:hasItem(reward) then\n                            player:messageSpecial(ID.text.CANNOT_OBTAIN_ITEM, reward)\n                            return quest:noAction()\n                        end\n\n                        local animationNpc = GetNPCByID(npc:getID() + 1)\n                        if animationNpc then\n                            animationNpc:entityAnimationPacket('krtu')\n                        end\n\n                        quest:setLocalVar(player, 'Progress', 1)\n                        return quest:progressEvent(2)\n                    end\n                end,\n            },\n\n            onZoneOut = function(player)\n                player:messageSpecial(ID.text.MIMEO_JEWEL_OFFSET + 4, xi.keyItem.MIMEO_STONE)\n                player:delKeyItem(xi.keyItem.MIMEO_STONE)\n            end,\n\n            onEventFinish =\n            {\n                [2] = function(player, csid, option, npc)\n                    player:delKeyItem(xi.keyItem.MIMEO_STONE)\n                    local numFades = quest:getLocalVar(player, 'NumFades')\n                    npcUtil.giveItem(player, rewards[numFades])\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Moghouse_Exposition.lua"]={["Path"]="scripts/quests/hiddenQuests/Moghouse_Exposition.lua",["SHA256"]="3e1366d7d5a6a890e6b6523db76f5fe08a3ca8cd2983ce28c41d4164c4ba0586",["Text"]="-----------------------------------\n-- Moghouse Exposition\n-----------------------------------\n\nlocal quest = HiddenQuest:new('moghouseExpo')\n\nquest.reward      = {}\nquest.sections    = {}\nquest.sections[1] = {}\nquest.sections[2] = {}\n\nlocal moogleZoneInEvent =\n{\n    onZoneIn =\n    {\n        function(player, prevZone)\n            return 30000\n        end,\n    },\n\n    onEventFinish =\n    {\n        [30000] = function(player, csid, option, npc)\n            quest:complete(player)\n            quest:setVar(player, 'oNation', 1)\n        end,\n    },\n}\n\nlocal otherNationTriggerEvent =\n{\n    ['Moogle'] = quest:progressEvent(30001),\n\n    onEventFinish =\n    {\n        [30001] = function(player, csid, option, npc)\n            quest:complete(player)\n        end,\n    },\n}\n\nquest.sections[1].check = function(player, currentMission, missionStatus, vars)\n    return xi.moghouse.inMogHouseInHomeNation(player) and\n        quest:getVar(player, 'notSeen') == 1\nend\n\nquest.sections[2].check = function(player, currentMission, missionStatus, vars)\n    return not xi.moghouse.inMogHouseInHomeNation(player) and\n        player:inMogHouse() and\n        quest:getVar(player, 'oNation') == 1\nend\n\nfor _, zoneId in ipairs(xi.moghouse.moghouseZones) do\n    quest.sections[1][zoneId] = moogleZoneInEvent\n    quest.sections[2][zoneId] = otherNationTriggerEvent\nend\n\nreturn quest\n"},["scripts/quests/hiddenQuests/Monstrosity_Bee.lua"]={["Path"]="scripts/quests/hiddenQuests/Monstrosity_Bee.lua",["SHA256"]="f6ce07bbac6a7087735de3687817efdc4f86067ab5c31324fae8f2fcae5be747",["Text"]="-----------------------------------\n-- Monstrosity: Suibhne Bee Guessing Game\n-----------------------------------\n-- Suibhne : !pos -366 -3.612 -466 285\n-----------------------------------\nlocal feretoryID = zones[xi.zone.FERETORY]\n-----------------------------------\n\nlocal quest = HiddenQuest:new('monstrosityBee')\n\nquest.reward = {}\n\nlocal choices =\n{\n    AENGUS  = 1,\n    MACCUS  = 2,\n    SUIBHNE = 3,\n    TEYRNON = 4,\n}\n\nlocal answerKey =\n{\n    [1] = { [0] = choices.TEYRNON, [1] = choices.AENGUS,  [2] = choices.SUIBHNE },\n    [2] = { [0] = choices.TEYRNON, [1] = choices.SUIBHNE, [2] = choices.AENGUS  },\n    [3] = { [0] = choices.AENGUS,  [1] = choices.TEYRNON, [2] = choices.SUIBHNE },\n    [4] = { [0] = choices.AENGUS,  [1] = choices.SUIBHNE, [2] = choices.TEYRNON },\n    [5] = { [0] = choices.SUIBHNE, [1] = choices.AENGUS,  [2] = choices.TEYRNON },\n    [6] = { [0] = choices.SUIBHNE, [1] = choices.TEYRNON, [2] = choices.AENGUS  },\n}\n\nlocal function getCheckValue(choiceNum)\n    local checkValue = 0\n\n    for fieldPos, correctChoice in pairs(answerKey[choiceNum]) do\n        checkValue = checkValue + bit.lshift(correctChoice, 16 + 3 * fieldPos)\n    end\n\n    return checkValue\nend\n\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return xi.settings.main.ENABLE_MONSTROSITY == 1 and\n                not xi.monstrosity.hasUnlockedSpecies(player, xi.monstrositySpecies.BEE)\n        end,\n\n        [xi.zone.FERETORY] =\n        {\n            ['Suibhne'] =\n            {\n                onTrigger = function(player, npc)\n                    local quizInfo = quest:getVar(player, 'Option')\n\n                    if quizInfo == 0 then\n                        quizInfo = math.randomInt(1, 6)\n                        quest:setVar(player, 'Option', quizInfo)\n                    end\n\n                    xi.monstrosity.suibhneGreet(player, npc)\n\n                    -- A wrong answer locks the quiz until the next Vana'diel day. Retail still sends the quiz.\n                    local available = quest:getVar(player, 'Timer') <= VanadielUniqueDay() and 1 or 0\n\n                    return quest:progressEvent(11, available, quizInfo - 1)\n                end,\n            },\n\n            onEventFinish =\n            {\n                [11] = function(player, csid, option, npc)\n                    if quest:getVar(player, 'Timer') > VanadielUniqueDay() then\n                        return\n                    end\n\n                    if option == 1 + getCheckValue(quest:getVar(player, 'Option')) then\n                        if quest:complete(player) then\n                            xi.monstrosity.unlockSpecies(player, xi.monstrositySpecies.BEE)\n                            player:messageSpecial(feretoryID.text.MAY_POSSESS_BEES)\n                        end\n                    elseif option == 2 then\n                        quest:setVar(player, 'Timer', VanadielUniqueDay() + 1)\n                    end\n                end,\n            },\n        },\n    },\n}\n\nreturn quest\n"},["scripts/quests/hiddenQuests/New_Character_Cutscenes.lua"]={["Path"]="scripts/quests/hiddenQuests/New_Character_Cutscenes.lua",["SHA256"]="c1ea47ed760971454d3f8e7af7cfc464c160306574f95a79ef74badcb2bcd041",["Text"]="-----------------------------------\n-- New Character Cutscenes\n-----------------------------------\nlocal quest = HiddenQuest:new('newCharacterCS')\n\nquest.reward = {}\n\n-- Note:\n-- Some areas swap order of when you get the Adventurer's coupon and the marker help text.\n-- On retail, even if your inventory is full and change nations, the starting cutscene will attempt to give you the Adventurer's coupon and report your inventory is full.\nquest.sections =\n{\n    {\n        check = function(player, questVars, vars)\n            return quest:getVar(player, 'notSeen') == 1 and xi.settings.main.NEW_CHARACTER_CUTSCENE == 1\n        end,\n\n        [xi.zone.BASTOK_MARKETS] =\n        {\n            onZoneIn =\n            {\n                function(player, prevZone)\n                    player:setPos(-280, -12, -90, 0)\n                    if quest:getVar(player, 'nations') == 0 then\n                        player:setHomePoint()\n                    end\n\n                    local cutsceneFlags = bit.bor(\n                        xi.cutsceneFlag.RESET_CAMERA,\n                        xi.cutsceneFlag.NO_PCS,\n                        xi.cutsceneFlag.OPENING_MODE\n                    )\n\n                    return { 0, -1, cutsceneFlags } -- CS 0 is not a typo.\n                end\n            },\n\n            onEventFinish =\n            {\n                [0] = function(player, csid, option, npc)\n                    -- Retail normally zones you for this -- but testing proved there was no difference other than NOT zoning by just calling the next event.\n                    -- event 0x00 fades your screen to black and seems to wait for another event, otherwise it will never fade back in.\n                    -- I think retail uses zoning to set the \"isHidden\" state we use for events.\n\n                    local cutsceneFlags = bit.bor(\n                        xi.cutsceneFlag.RESET_CAMERA,\n                        xi.cutsceneFlag.NO_PCS,\n                        xi.cutsceneFlag.OPENING_MODE\n                    )\n\n                    player:startEvent(7, { flags = cutsceneFlags, isHidden = true })\n                end,\n\n                [7] = function(player, csid, option, npc)\n                    local ID = zones[player:getZoneID()]\n                    -- If you don't get the coupon, tough luck. Retail doesn't give you a chance to get it again.\n                    npcUtil.giveItem(player, xi.item.ADVENTURER_COUPON)\n                    player:messageText(player, ID.text.MAP_MARKER_TUTORIAL)\n\n                    quest:setVar(player, 'notSeen', 0)\n                    local nationsSeen = quest:getVar(player, 'nations')\n                    quest:setVar(player, 'nations', utils.mask.setBit(nationsSeen, xi.nation.BASTOK, true))\n                end,\n            },\n        },\n\n        [xi.zone.BASTOK_MINES] =\n        {\n            onZoneIn =\n            {\n                function(player, prevZone)\n                    player:setPos(-45, -0, 25, 192)\n                    if quest:getVar(player, 'nations') == 0 then\n                        player:setHomePoint()\n                    end\n\n                    local cutsceneFlags = bit.bor(\n                        xi.cutsceneFlag.RESET_CAMERA,\n                        xi.cutsceneFlag.NO_PCS,\n                        xi.cutsceneFlag.OPENING_MODE\n                    )\n                    return { 1, -1, cutsceneFlags }\n                end\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    local ID = zones[player:getZoneID()]\n                    -- If you don't get the coupon, tough luck. Retail doesn't give you a chance to get it again.\n                    npcUtil.giveItem(player, xi.item.ADVENTURER_COUPON)\n                    player:messageText(player, ID.text.MAP_MARKER_TUTORIAL)\n\n                    quest:setVar(player, 'notSeen', 0)\n                    local nationsSeen = quest:getVar(player, 'nations')\n                    quest:setVar(player, 'nations', utils.mask.setBit(nationsSeen, xi.nation.BASTOK, true))\n                end,\n            },\n        },\n\n        [xi.zone.PORT_BASTOK] =\n        {\n            onZoneIn =\n            {\n                function(player, prevZone)\n                    player:setPos(134, 8.5, -11, 96)\n                    if quest:getVar(player, 'nations') == 0 then\n                        player:setHomePoint()\n                    end\n\n                    local cutsceneFlags = bit.bor(\n                        xi.cutsceneFlag.RESET_CAMERA,\n                        xi.cutsceneFlag.NO_PCS,\n                        xi.cutsceneFlag.OPENING_MODE\n                    )\n                    return { 1, -1, cutsceneFlags }\n                end\n            },\n\n            onEventFinish =\n            {\n                [1] = function(player, csid, option, npc)\n                    local ID = zones[player:getZoneID()]\n                    player:messageText(player, ID.text.MAP_MARKER_TUTORIAL)\n                    -- If you don't get the coupon, tough luck. Retail doesn't give you a chance to get it again.\n                    npcUtil.giveItem(player, xi.item.ADVENTURER_COUPON)\n\n                    quest:setVar(player, 'notSeen', 0)\n                    local nationsSeen = quest:getVar(player, 'nations')\n                    quest:setVar(player, 'nations', utils.mask.setBit(nationsSeen, xi.nation.BASTOK, true))\n                end,\n            },\n        },\n\n        [xi.zone.NORTHERN_SAN_DORIA] =\n        {\n            onZoneIn =\n            {\n                function(player, prevZone)\n                    player:setPos(0, 0, -12, 192)\n                    if quest:getVar(player, 'nations') == 0 then\n                        player:setHomePoint()\n                    end\n\n                    local cutsceneFlags = bit.bor(\n                        xi.cutsceneFlag.RESET_CAMERA,\n                        xi.cutsceneFlag.NO_PCS,\n                        xi.cutsceneFlag.OPENING_MODE\n                    )\n\n                    return { 535, -1, cutsceneFlags }\n                end\n            },\n\n            onEventFinish =\n            {\n                [535] = function(player, csid, option, npc)\n                    local ID = zones[player:getZoneID()]\n                    player:messageText(player, ID.text.MAP_MARKER_TUTORIAL)\n                    -- If you don't get the coupon, tough luck. Retail doesn't give you a chance to get it again.\n                    npcUtil.giveItem(player, xi.item.ADVENTURER_COUPON)\n\n                    quest:setVar(player, 'notSeen', 0)\n                    local nationsSeen = quest:getVar(player, 'nations')\n                    quest:setVar(player, 'nations', utils.mask.setBit(nationsSeen, xi.nation.SANDORIA, true))\n                end,\n            },\n        },\n\n        [xi.zone.SOUTHERN_SAN_DORIA] =\n        {\n            onZoneIn =\n            {\n                function(player, prevZone)\n                    player:setPos(-100, 1, -40, 224) --cs exit\n                    if quest:getVar(player, 'nations') == 0 then\n                        player:setHomePoint()\n                    end\n\n                    local cutsceneFlags = bit.bor(\n                        xi.cutsceneFlag.RESET_CAMERA,\n                        xi.cutsceneFlag.NO_PCS,\n                        xi.cutsceneFlag.OPENING_MODE\n                    )\n\n                    return { 503, -1, cutsceneFlags }\n                end\n            },\n\n            onEventFinish =\n            {\n                [503] = function(player, csid, option, npc)\n                    local ID = zones[player:getZoneID()]\n                    player:messageText(player, ID.text.MAP_MARKER_TUTORIAL)\n                    -- If you don't get the coupon, tough luck. Retail doesn't give you a chance to get it again.\n                    npcUtil.giveItem(player, xi.item.ADVENTURER_COUPON)\n\n                    quest:setVar(player, 'notSeen', 0)\n                    local nationsSeen = quest:getVar(player, 'nations')\n                    quest:setVar(player, 'nations', utils.mask.setBit(nationsSeen, xi.nation.SANDORIA, true))\n                end,\n            },\n        },\n\n        [xi.zone.PORT_SAN_DORIA] =\n        {\n            onZoneIn =\n            {\n                function(player, prevZone)\n                    player:setPos(-100, -8, -125, 224)\n                    if quest:getVar(player, 'nations') == 0 then\n                        player:setHomePoint()\n                    end\n\n                    local cutsceneFlags = bit.bor(\n                        xi.cutsceneFlag.RESET_CAMERA,\n                        xi.cutsceneFlag.NO_PCS,\n                        xi.cutsceneFlag.OPENING_MODE\n                    )\n\n                    return { 500, -1, cutsceneFlags }\n                end\n            },\n\n            onEventFinish =\n            {\n                [500] = function(player, csid, option, npc)\n                    local ID = zones[player:getZoneID()]\n                    -- If you don't get the coupon, tough luck. Retail doesn't give you a chance to get it again.\n                    npcUtil.giveItem(player, xi.item.ADVENTURER_COUPON)\n                    player:messageText(player, ID.text.MAP_MARKER_TUTORIAL)\n\n                    quest:setVar(player, 'notSeen', 0)\n                    local nationsSeen = quest:getVar(player, 'nations')\n                    quest:setVar(player, 'nations', utils.mask.setBit(nationsSeen, xi.nation.SANDORIA, true))\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WATERS] =\n        {\n            onZoneIn =\n            {\n                function(player, prevZone)\n                    -- The HP position is slightly different than the CS exit.\n                    if quest:getVar(player, 'nations') == 0 then\n                        player:setPos(-40.0, -5, 100, 64)\n                        player:setHomePoint()\n                    end\n\n                    player:setPos(-40.611, -5, 102.5, 57) -- Move back to CS exit position\n\n                    local cutsceneFlags = bit.bor(\n                        xi.cutsceneFlag.RESET_CAMERA,\n                        xi.cutsceneFlag.NO_PCS,\n                        xi.cutsceneFlag.NO_NPCS,\n                        xi.cutsceneFlag.OPENING_MODE\n                    )\n\n                    return { 531, -1, cutsceneFlags }\n                end\n            },\n\n            onEventUpdate =\n            {\n                [531] = function(player, csid, option, npc)\n                    -- param 7 is checked in the event according to decomp, but it was never set on Hume F starting a new character.\n                    -- param 7 was 0x20012 on a galka changing nations.\n                    player:updateEvent({ [7] = 0 })\n                end,\n            },\n\n            onEventFinish =\n            {\n                [531] = function(player, csid, option, npc)\n                    local ID = zones[player:getZoneID()]\n                    player:messageText(player, ID.text.MAP_MARKER_TUTORIAL)\n                    -- If you don't get the coupon, tough luck. Retail doesn't give you a chance to get it again.\n                    npcUtil.giveItem(player, xi.item.ADVENTURER_COUPON)\n\n                    quest:setVar(player, 'notSeen', 0)\n                    local nationsSeen = quest:getVar(player, 'nations')\n                    quest:setVar(player, 'nations', utils.mask.setBit(nationsSeen, xi.nation.WINDURST, true))\n                end,\n            },\n        },\n\n        [xi.zone.WINDURST_WOODS] =\n        {\n            onZoneIn =\n            {\n                function(player, prevZone)\n                    player:setPos(30, 2, -40, 128)\n                    if quest:getVar(player, 'nations') == 0 then\n                        player:setHomePoint()\n                    end\n\n                    local cutsceneFlags = bit.bor(\n                        xi.cutsceneFlag.RESET_CAMERA,\n                        xi.cutsceneFlag.NO_PCS,\n                        xi.cutsceneFlag.NO_NPCS,\n                        xi.cutsceneFlag.OPENING_MODE\n                    )\n                    return { 367, -1, cutsceneFlags }\n                end\n            },\n\n            onEventFinish =\n            {\n                [367] = 